/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"보험계약의 의의와 법적 성질":{"묶음":[{"머리":"보험계약의 정의","줄":[{"t":"보험계약: 당사자 일방이 약정한 보험료를 지급하고, 재산 또는 생명이나 신체에 불확정한 사고가 발생할 경우에 상대방이 일정한 보험금이나 그 밖의 급여를 지급할 것을 약정함으로써 효력이 생기는 계약.","src":"상법 제638조"},{"t":"보험금 외에 「그 밖의 급여」(현물 등)를 지급하기로 약정할 수도 있다.","src":"상법 제638조 | 기출 2022-1"}]},{"머리":"법적 성질","줄":[{"t":"낙성계약: 청약과 승낙의 합의만으로 성립한다. 증권 교부는 성립요건이 아니다.","src":"기출 2025-1 | 기출 2024-2"},{"t":"불요식계약: 일정한 방식을 요하지 않는다.","src":"기출 2025-1"},{"t":"유상·쌍무계약: 보험료와 보험금 지급 약속이 대가관계에 있다. 「유상·편무」는 틀린 표현.","src":"기출 2021-1 | 기출 2025-1"},{"t":"사행계약: 보험자의 보험금 지급 책임이 우연한 사고 발생에 달려 있다.","src":"기출 2021-1"},{"t":"선의계약: 고지의무 등 신의성실이 특히 요구된다.","src":"기출 2025-1"},{"t":"부합계약: 보험약관에 따라 정형적으로 체결된다.","src":"기출 2021-1 | 기출 2025-1"},{"t":"청약은 보험계약자가 하고 보험자가 승낙한다. 「보험자의 청약에 보험계약자가 승낙」은 틀린 표현.","src":"기출 2021-1"}]},{"머리":"당사자와 관계자(손해보험)","줄":[{"t":"보험자: 보험사고가 발생한 경우 보험금 지급의무를 지는 자.","src":"기출 2024-1"},{"t":"보험계약자: 자기 명의로 보험계약을 체결하고 보험료 지급의무를 지는 자.","src":"기출 2024-1"},{"t":"피보험자: 피보험이익의 주체로서 보험사고가 발생한 때 보험금을 받을 자.","src":"기출 2024-1"},{"t":"보험수익자: 인보험에서 보험금을 지급받을 자로 지정된 자. 손해보험에서 보험금을 받는 자는 피보험자.","src":"보충 | 기출 2024-1"}]},{"머리":"보험기간의 시기와 소급보험","줄":[{"t":"소급보험: 보험계약은 그 계약 전의 어느 시기를 보험기간의 시기로 할 수 있다.","src":"상법 제643조"},{"t":"보험기간의 시기를 보험계약 체결 시점과 같게 하여야 하는 것은 아니다.","src":"기출 2022-1"}]},{"머리":"보험사고의 객관적 확정","줄":[{"t":"계약 당시 보험사고가 이미 발생하였거나 발생할 수 없는 것인 때에는 그 계약은 무효. (무효이지 취소 사유가 아님)","src":"상법 제644조 본문 | 기출 2026-3"},{"t":"예외: 당사자 쌍방과 피보험자가 이를 알지 못한 때에는 유효. 셋 중 한 명이라도 알았으면 무효.","src":"상법 제644조 단서 | 기출 2022-4 | 기출 2025-4"},{"t":"사례: 보험사고 이미 발생을 보험계약자(B)가 알고 체결 → 무효. 발생 불가능을 계약자(A)가 알면서 체결 → 무효. A·B·C 모두 몰랐으면 유효.","src":"기출 2022-4"}]},{"머리":"사고 발생 전·후의 임의해지","줄":[{"t":"보험사고 발생 전에는 보험계약자가 언제든지 계약의 전부 또는 일부를 해지할 수 있다.","src":"상법 제649조① | 기출 2023-4"},{"t":"타인을 위한 보험(제639조)의 경우 타인의 동의를 얻지 아니하거나 보험증권을 소지하지 아니하면 해지하지 못한다.","src":"상법 제649조① 단서"},{"t":"보험사고로 보험금을 지급해도 보험금액이 감액되지 아니하는 보험은 사고 발생 후에도 보험계약자가 해지할 수 있다.","src":"상법 제649조② | 기출 2024-7"},{"t":"사고 발생 전 임의해지의 경우, 다른 약정이 없으면 미경과보험료의 반환을 청구할 수 있다.","src":"상법 제649조③"}]},{"머리":"보험료 감액과 준용","줄":[{"t":"당사자가 특별한 위험을 예기하여 보험료의 액을 정한 경우 보험기간 중 그 위험이 소멸하면 보험계약자는 그 후의 보험료 감액을 청구할 수 있다.","src":"상법 제647조 | 기출 2026-5"},{"t":"상법 보험편의 규정은 그 성질에 반하지 아니하는 범위에서 상호보험, 공제, 그 밖에 이에 준하는 계약에 준용한다.","src":"상법 제664조 | 기출 2022-13"},{"t":"피보험자는 보험사고 발생을 안 때 지체없이 보험자에게 통지를 발송하여야 한다.","src":"상법 제657조① | 기출 2023-4"}]}],"함정":[{"x":"상법 보험편의 규정은 약관에 의하여 피보험자나 보험수익자의 이익으로 변경할 수 없다.","o":"상법 보험편의 규정은 약관으로도 피보험자·수익자의 이익으로 변경할 수 있다(불이익 변경만 금지).","src":"상법 제663조 | 기출 2022-13"},{"x":"보험계약 당시에 보험사고가 발생할 수 없음이 객관적으로 확정된 경우 당사자 쌍방과 피보험자가 이를 알았는지 여부에 관계없이 그 계약은 무효로 한다.","o":"사고가 발생할 수 없음이 객관적으로 확정된 경우에도 당사자 쌍방과 피보험자가 알지 못한 때에는 유효하다.","src":"상법 제644조 | 기출 2023-4"},{"x":"손해보험의 보험수익자는 보험사고가 발생한 때에 보험금을 지급받을 자로 지정된 자이다.","o":"손해보험에서 보험금을 받을 자는 피보험자이고, 보험수익자는 인보험에서 보험금을 받을 자로 지정된 자이다.","src":"보충 | 기출 2024-1 | 기출 2024-1"},{"x":"보험사고가 발생하기 전에 보험계약을 해지한 보험계약자는 미경과보험료의 반환을 청구할 수 없다.","o":"사고 발생 전 해지한 보험계약자는 다른 약정이 없으면 미경과보험료의 반환을 청구할 수 있다.","src":"상법 제649조③ | 기출 2024-7"},{"x":"보험사고의 발생으로 보험자가 보험금액을 지급한 때에도 보험금액이 감액되지 아니 하는 보험의 경우에는 보험계약자가 그 사고발생 후에 보험계약을 해지할 수 없다.","o":"보험금액이 감액되지 아니하는 보험은 사고 발생 후에도 보험계약자가 계약을 해지할 수 있다.","src":"상법 제649조② | 기출 2025-4"},{"x":"보험계약 당시에 보험사고가 객관적으로 발생할 수 없음을 보험계약자와 보험자가 몰랐다면, 피보험자가 이를 알았더라도 그 계약은 무효로 볼 수 없다.","o":"사고 발생 불가능 사실을 당사자 쌍방과 피보험자 중 누구라도 알았으면 계약은 무효이다(피보험자가 알았으면 무효).","src":"상법 제644조 | 기출 2025-4"},{"x":"계약전의 어느 시기를 보험기간의 시기(始期)로 한 보험계약은 무효이다.","o":"소급보험도 유효하다.","src":"상법 제643조 | 기출 2025-4"},{"x":"보험계약당시에 보험사고가 이미 발생한 때에는 그 계약은 취소할 수 있다.","o":"계약 당시 사고가 이미 발생한 때에는 (취소가 아니라) 계약은 무효이다(쌍방·피보험자가 몰랐으면 유효).","src":"상법 제644조 | 기출 2026-3"},{"x":"보험계약의 일부가 무효인 경우에 보험계약자 또는 피보험자가 선의이며 중대한 과실 이 없는 때에는 보험자에 대하여 보험료의 반환을 청구할 수 있다.","o":"일부 무효 시 보험료 반환은 보험계약자와 피보험자(또는 보험계약자와 보험수익자)가 모두 선의이며 중대한 과실이 없어야 청구할 수 있다.","src":"상법 제648조 | 기출 2026-5"}]},"보험계약의 요소와 성립ㆍ보험약관":{"묶음":[{"머리":"보험계약의 요소","줄":[{"t":"보험계약의 보조자: 보험대리상, 보험설계사, 보험중개사 등(권한은 보험대리상 쟁점 참조).","src":"보충"},{"t":"보험계약의 관계자: 보험자, 보험계약자, 피보험자, 보험수익자.","src":"보충"},{"t":"보험계약자는 보험자에 대하여 보험료를 지급할 의무가 있다.","src":"상법 제639조③ | 기출 2023-2"}]},{"머리":"보험계약의 성립","줄":[{"t":"낙부 통지: 보험자가 청약과 함께 보험료 상당액의 전부 또는 일부를 받은 때에는 다른 약정이 없으면 30일 내에 보험계약자에게 낙부의 통지를 발송하여야 한다.","src":"상법 제638조의2① | 기출 2022-1 | 기출 2023-1"},{"t":"인보험 피보험자가 신체검사를 받아야 하는 경우, 30일은 신체검사를 받은 날부터 기산한다.","src":"상법 제638조의2① 단서"},{"t":"보험자가 위 기간 내에 낙부 통지를 해태한 때에는 승낙한 것으로 본다.","src":"상법 제638조의2② | 기출 2023-1"},{"t":"승낙 전 사고: 청약과 함께 보험료 상당액을 받은 뒤 승낙 전에 사고가 생기면, 청약을 거절할 사유가 없는 한 보험자는 보험계약상 책임을 진다. 거절 사유가 있으면 책임이 없다.","src":"상법 제638조의2③ | 기출 2023-1"},{"t":"예외: 인보험 피보험자가 신체검사를 받아야 하는데 받지 않은 때에는 위 책임을 지지 않는다.","src":"상법 제638조의2③ 단서"},{"t":"보험료 상당액을 받았다는 사실만으로 계약이 성립한 것으로 보지 않는다. 낙부 통지 해태 시 승낙 간주.","src":"기출 2024-2"},{"t":"보험자의 책임 개시: 다른 약정이 없으면 최초 보험료의 지급을 받은 때.","src":"상법 제656조 | 기출 2024-10"}]},{"머리":"보험약관의 교부·설명의무","줄":[{"t":"보험자는 보험계약을 체결할 때 보험계약자에게 보험약관을 교부하고 그 약관의 중요한 내용을 설명하여야 한다. (성립 후가 아님)","src":"상법 제638조의3① | 기출 2024-2"},{"t":"보험자가 위 의무를 위반하면 보험계약자는 보험계약이 성립한 날부터 3개월 이내에 그 계약을 취소할 수 있다. 취소권자는 보험계약자(피보험자·수익자 아님).","src":"상법 제638조의3② | 기출 2021-8 | 기출 2022-2"},{"t":"성립일부터 1개월 시점은 취소 가능, 4개월 시점은 취소 불가.","src":"기출 2022-2 | 기출 2026-2"},{"t":"약관의 구속력 근거: 당사자가 약관을 계약 내용에 포함시키기로 합의했기 때문(계약설).","src":"기출 2021-8"},{"t":"약관 내용이 이미 법령에 정해진 것을 되풀이하는 정도에 불과한 경우, 보험자는 따로 설명하지 않아도 된다.","src":"기출 2021-8"}]},{"머리":"타인을 위한 보험","줄":[{"t":"보험계약자는 위임을 받거나 받지 아니하고, 특정 또는 불특정의 타인을 위하여 보험계약을 체결할 수 있다.","src":"상법 제639조① | 기출 2023-2 | 기출 2026-3"},{"t":"손해보험에서 타인의 위임이 없는 때에는 보험계약자가 이를 보험자에게 고지하여야 하고, 고지가 없으면 타인이 계약 체결 사실을 알지 못하였다는 사유로 보험자에게 대항하지 못한다.","src":"상법 제639조① 단서 | 기출 2024-6"},{"t":"그 타인은 수익의 의사표시 없이 당연히 계약의 이익을 받는다.","src":"상법 제639조②"},{"t":"손해보험에서 보험계약자가 타인에게 사고로 생긴 손해를 배상한 때에는, 타인의 권리를 해하지 아니하는 범위에서 보험자에게 보험금액의 지급을 청구할 수 있다.","src":"상법 제639조② 단서 | 기출 2025-2"},{"t":"보험료는 보험계약자가 낼 의무가 있다. 보험계약자가 파산선고를 받거나 보험료 지급을 지체한 때에는, 타인이 그 권리를 포기하지 않는 한 타인도 보험료를 지급할 의무가 있다.","src":"상법 제639조③ | 기출 2021-2 | 기출 2023-2"},{"t":"특정한 타인을 위한 보험에서 보험료 지급이 지체되면 보험자는 그 타인에게도 상당한 기간을 정해 최고한 후가 아니면 해제·해지하지 못한다.","src":"상법 제650조③"},{"t":"계약 체결 시 타인이 특정되어 있을 필요는 없다.","src":"기출 2023-2"}]},{"머리":"대리인에 의한 체결","줄":[{"t":"대리인에 의하여 보험계약을 체결한 경우 대리인이 안 사유는 본인이 안 것과 동일한 것으로 한다.","src":"상법 제646조 | 기출 2022-5"}]}],"함정":[{"x":"보험계약자는 위임을 받지 아니하면 특정의 타인을 위하여 보험계약을 체결할 수 없다.","o":"보험계약자는 위임을 받거나 받지 아니하고 특정 또는 불특정의 타인을 위하여 보험계약을 체결할 수 있다.","src":"상법 제639조① | 기출 2021-2"},{"x":"타인을 위한 보험계약의 경우에 그 타인은 수익의 의사표시를 하여야 그 계약의 이익을 받을 수 있다.","o":"타인을 위한 보험계약에서 그 타인은 수익의 의사표시를 하지 않아도 당연히 그 계약의 이익을 받는다.","src":"상법 제639조② | 기출 2021-2"},{"x":"보험계약자가 불특정의 타인을 위한 보험을 그 타인의 위임 없이 체결할 경우에는 이를 보험자에게 고지할 필요가 없다.","o":"손해보험에서 타인의 위임 없이 체결하는 경우 보험계약자는 이를 보험자에게 고지하여야 하고, 고지가 없으면 타인이 계약 체결 사실을 알지 못하였다는 사유로 보험자에게 대항하지 못한다.","src":"상법 제639조① | 기출 2021-2"},{"x":"보험계약자가 보험계약을 취소하지 않았다면 甲보험회사는 중요한 약관조항을 계약의 내용으로 주장할 수 있다.","o":"설명의무를 위반한 경우 보험계약자가 취소하지 않았더라도 보험자는 그 약관 조항을 계약 내용으로 주장할 수 없다(판례 취지, 추정).","src":"보충(추정) | 기출 2022-2 | 기출 2022-2"},{"x":"승낙하기 전에 발생한 보험사고에 대해서 청약을 거절할 사유가 있더라도 보험자는 보험계약상의 책임을 진다.","o":"승낙 전 사고가 생겨도 청약 거절 사유가 없으면 보험자는 보험계약상 책임을 지고, 거절 사유가 있으면 책임이 없다.","src":"상법 제638조의2③ | 기출 2023-1"},{"x":"타인은 계약 성립 시 특정되어야 한다.","o":"타인은 불특정이어도 되므로 계약 성립 시 특정될 필요가 없다.","src":"상법 제639조① | 기출 2023-2"},{"x":"보험계약은 청약과 승낙에 의한 합의와 보험증권의 교부로 성립한다.","o":"보험계약은 불요식 낙성계약으로 청약과 승낙의 합의로 성립하며 증권 교부는 성립요건이 아니다.","src":"상법 제638조 | 기출 2024-2"},{"x":"보험자는 보험계약이 성립된 후 보험계약자에게 보험약관을 교부하고 그 약관의 중요 한 내용을 설명하여야 한다.","o":"보험자는 보험계약을 「체결할 때」 약관을 교부하고 중요한 내용을 설명하여야 한다(성립 후 아님).","src":"상법 제638조의3① | 기출 2024-2"},{"x":"보험자가 보험계약자로부터 보험계약의 청약과 함께 보험료 상당액의 전부 또는 일부의 지급을 받은 때에는 계약이 성립한 것으로 본다.","o":"청약과 함께 보험료 상당액을 받아도 계약이 성립한 것으로 보지는 않고, 30일 내 낙부 통지를 해태한 때 승낙한 것으로 본다.","src":"상법 제638조의2 | 기출 2024-2"},{"x":"보험사고가 발생하기 전에는 甲은 언제든지 계약의 전부 또는 일부를 해지할 수 있다.","o":"자기를 위한 보험은 사고 전 언제든지 전부 또는 일부 해지할 수 있으나, 타인을 위한 보험은 타인의 동의와 증권 소지가 있어야 한다.","src":"상법 제649조① | 기출 2024-6"},{"x":"A가 보험약관의 설명의무를 위반한 경우 甲은 계약이 성립한 날부터 4개월 후에 그 계약을 취소할 수 있다.","o":"약관 설명의무 위반 시 계약이 성립한 날부터 3개월 이내에 취소할 수 있으므로 4개월 후에는 취소할 수 없다.","src":"상법 제638조의3② | 기출 2026-2"}]},"보험증권":{"묶음":[{"머리":"증권의 교부","줄":[{"t":"보험자는 보험계약이 성립한 때 지체없이 보험증권을 작성하여 보험계약자에게 교부하여야 한다.","src":"상법 제640조① | 기출 2024-3"},{"t":"예외: 보험계약자가 보험료 전부 또는 최초 보험료를 지급하지 아니한 때에는 교부 의무가 없다.","src":"상법 제640조① 단서 | 기출 2022-3 | 기출 2026-3"},{"t":"기존 보험계약을 연장하거나 변경한 경우, 보험자는 보험증권에 그 사실을 기재함으로써 증권 교부에 갈음할 수 있다.","src":"상법 제640조② | 기출 2023-3 | 기출 2026-1"},{"t":"교부 상대방은 보험계약자이다. 타인을 위한 보험이라도 타인에게 교부하는 것이 아니다.","src":"상법 제640조① | 기출 2024-3"}]},{"머리":"이의약관·재교부","줄":[{"t":"보험계약의 당사자는 증권 교부일부터 일정한 기간 내에 한하여 증권 내용의 정부(正否)에 관한 이의를 할 수 있음을 약정할 수 있다. 이 기간은 1월을 내리지 못한다.","src":"상법 제641조 | 기출 2021-3 | 기출 2023-3"},{"t":"증권을 멸실 또는 현저하게 훼손한 때 보험계약자는 보험자에게 재교부를 청구할 수 있고, 증권 작성 비용은 보험계약자가 부담한다.","src":"상법 제642조 | 기출 2022-3 | 기출 2026-1"}]},{"머리":"손해보험증권의 법정기재사항(보험자가 기명날인 또는 서명)","줄":[{"t":"1호 보험의 목적","src":"상법 제666조"},{"t":"2호 보험사고의 성질","src":"상법 제666조 | 기출 2023-10"},{"t":"3호 보험금액","src":"상법 제666조 | 기출 2022-14"},{"t":"4호 보험료와 그 지급방법","src":"상법 제666조 | 기출 2024-14"},{"t":"5호 보험기간을 정한 때에는 그 시기와 종기","src":"상법 제666조"},{"t":"6호 무효와 실권의 사유","src":"상법 제666조 | 기출 2022-14 | 기출 2023-10"},{"t":"7호 보험계약자의 주소와 성명 또는 상호","src":"상법 제666조"},{"t":"7호의2 피보험자의 주소, 성명 또는 상호","src":"상법 제666조"},{"t":"8호 보험계약의 연월일","src":"상법 제666조"},{"t":"9호 보험증권의 작성지와 그 작성년월일","src":"상법 제666조 | 기출 2023-10"},{"t":"기재사항이 아닌 것: 보험수익자의 주소·성명, 피보험자의 주민등록번호, 청약철회 사유, 보험료의 계산방법, 보험자의 면책에 관한 사항, 보험계약자의 기명날인, 보험금액의 지급방법·시기.","src":"기출 2022-14 | 기출 2024-14 | 기출 2025-14 | 기출 2026-13"},{"t":"증권에 기명날인 또는 서명하는 자는 보험자이다.","src":"상법 제666조 | 기출 2023-10"}]},{"머리":"화재보험증권의 추가 기재사항","줄":[{"t":"제666조 사항 외에 1호 건물이 목적이면 그 소재지, 구조와 용도","src":"상법 제685조 | 기출 2021-24 | 기출 2024-24"},{"t":"2호 동산이 목적이면 그 존치한 장소의 상태와 용도","src":"상법 제685조 | 기출 2024-24 | 기출 2026-24"},{"t":"3호 보험가액을 정한 때에는 그 가액","src":"상법 제685조 | 기출 2021-24"},{"t":"화재보험증권 기재사항이 아닌 것: 설계감리법인의 주소·성명, 건물 시공자의 주소·성명.","src":"기출 2021-24 | 기출 2026-24"}]}],"함정":[{"x":"보험증권의 멸실로 보험계약자가 증권의 재교부를 청구한 경우 증권의 작성비용은 보험자의 부담으로 한다.","o":"증권을 멸실 또는 현저하게 훼손하여 재교부를 청구한 경우 증권 작성 비용은 보험계약자가 부담한다.","src":"상법 제642조 | 기출 2021-3"},{"x":"보험기간의 시기는 보험계약 이후로만 하여야 한다.","o":"보험계약은 그 계약 전의 어느 시기를 보험기간의 시기로 할 수 있다(소급보험).","src":"상법 제643조 | 기출 2021-3"},{"x":"보험계약당시에 보험사고가 이미 발생하였을 경우 당사자 쌍방과 피보험자가 이를 알지 못하였어도 그 계약은 무효이다.","o":"계약 당시 보험사고가 이미 발생한 경우에도 당사자 쌍방과 피보험자가 이를 알지 못한 때에는 계약은 유효하다.","src":"상법 제644조 | 기출 2021-3"},{"x":"기존의 보험계약을 변경한 경우 보험자는 그 보험증권에 그 사실을 기재함으로써 보험증권의 교부에 갈음할 수 없다.","o":"기존 계약을 연장하거나 변경한 경우 보험자는 증권에 그 사실을 기재함으로써 증권 교부에 갈음할 수 있다.","src":"상법 제640조② | 기출 2022-3"},{"x":"타인을 위한 보험계약이 성립된 경우에는 보험자는 그 타인에게 보험증권을 교부해야 한다.","o":"타인을 위한 보험에서도 증권 교부의 상대방은 보험계약자이다.","src":"상법 제640조① | 기출 2022-3"},{"x":"보험계약자가 최초의 보험료를 지급하지 아니한 경우에도 보험계약이 성립한 때에는 보험자는 지체없이 보험증권을 작성하여 보험계약자에게 교부하여야 한다.","o":"보험계약자가 보험료 전부 또는 최초 보험료를 지급하지 아니한 때에는 증권 교부 의무가 없다.","src":"상법 제640조① | 기출 2022-3"},{"x":"보험자는 보험계약자의 청약이 있는 경우 보험료의 지급 여부와 상관없이 지체없이 보험증권을 작성하여 보험계약자에게 교부하여야 한다.","o":"보험계약자가 최초 보험료를 지급하지 아니한 때에는 증권 교부 의무가 없다.","src":"상법 제640조① | 기출 2023-3"},{"x":"보험계약의 당사자는 보험증권의 교부가 있은 날부터 14일내에 한하여 그 증권내용의 정부(正否)에 관한 이의를 할 수 있음을 약정할 수 있다.","o":"증권 내용의 정부에 관한 이의 약정 기간은 1월 이상이어야 한다(14일은 1월보다 짧아 불가).","src":"상법 제641조 | 기출 2023-3"},{"x":"보험계약자가 보험증권을 멸실한 경우 보험계약자는 보험자에게 증권의 재교부를 청구할 수 있으며, 그 증권작성의 비용은 보험자의 부담으로 한다.","o":"증권 재교부 청구는 가능하나 작성 비용은 보험계약자가 부담한다.","src":"상법 제642조 | 기출 2023-3"},{"x":"보험계약자가 기명날인하여야 한다.","o":"손해보험증권에는 보험자가 기명날인 또는 서명한다(보험계약자의 기명날인은 법정기재사항 아님).","src":"상법 제666조 | 기출 2023-10"},{"x":"타인을 위한 보험계약이 성립된 경우에는 보험자는 그 타인에게 보험증권을 교부해야 한다.","o":"타인을 위한 보험에서도 증권 교부 상대방은 보험계약자이다.","src":"상법 제640조① | 기출 2024-3"},{"x":"보험계약자가 최초의 보험료를 지급하지 아니한 때에도 보험자는 보험계약이 성립한 때에는 지체없이 보험증권을 작성하여 보험계약자에게 교부하여야 한다.","o":"보험계약자가 최초 보험료를 지급하지 아니한 때에는 증권 교부 의무가 없다.","src":"상법 제640조① | 기출 2025-3"},{"x":"보험계약의 당사자는 보험증권의 교부가 있은 날부터 14일 기간내에 한하여 그 증권 내용의 정부에 관한 이의를 할 수 있음을 약정할 수 있다.","o":"증권 내용의 정부에 관한 이의 약정 기간은 1월 이상이어야 한다(14일 불가).","src":"상법 제641조 | 기출 2025-3"},{"x":"보험계약자가 보험증권을 현저하게 훼손하여 증권의 재교부를 청구한 경우 그 비용은 보험자가 부담하여야 한다.","o":"증권을 현저히 훼손하여 재교부를 청구한 경우 작성 비용은 보험계약자가 부담한다.","src":"상법 제642조 | 기출 2025-3"},{"x":"보험계약의 당사자는 보험증권의 교부가 있은 날로부터 15일 내에 한하여 이의를 할 수 있음을 약정할 수 있다.","o":"증권 정부 이의 약정 기간은 1월 이상이어야 한다(15일 불가).","src":"상법 제641조 | 기출 2026-1"}]},"보험대리상 등의 권한":{"묶음":[{"머리":"보험대리상의 권한(제646조의2 제1항)","줄":[{"t":"1호 보험계약자로부터 보험료를 수령할 수 있는 권한","src":"상법 제646조의2①1호 | 기출 2021-4 | 기출 2024-8"},{"t":"2호 보험자가 작성한 보험증권을 보험계약자에게 교부할 수 있는 권한","src":"상법 제646조의2①2호"},{"t":"3호 보험계약자로부터 청약, 고지, 통지, 해지, 취소 등 보험계약에 관한 의사표시를 수령할 수 있는 권한","src":"상법 제646조의2①3호 | 기출 2021-4 | 기출 2024-8"},{"t":"4호 보험계약자에게 보험계약의 체결, 변경, 해지 등 보험계약에 관한 의사표시를 할 수 있는 권한","src":"상법 제646조의2①4호 | 기출 2021-4 | 기출 2026-4 | 기출 2026-5"},{"t":"보험금 수령 권한은 법정 권한에 없다.","src":"상법 제646조의2① | 기출 2024-8"}]},{"머리":"권한 제한","줄":[{"t":"보험자는 보험대리상의 제1항 각 호 권한 중 일부를 제한할 수 있다. 다만 그러한 제한을 이유로 선의의 보험계약자에게 대항하지 못한다.","src":"상법 제646조의2② | 기출 2021-4"},{"t":"보험대리상의 권한을 전부 제한할 수 없다는 취지가 아니라, 일부 제한은 가능하되 선의의 계약자에게 대항 불가.","src":"상법 제646조의2② | 기출 2022-5 | 기출 2025-5 | 기출 2026-4"}]},{"머리":"보험대리상이 아닌 계속적 중개자(보험설계사 등)","줄":[{"t":"보험대리상이 아니면서 특정한 보험자를 위하여 계속적으로 보험계약의 체결을 중개하는 자는 제1항 제1호(보험자가 작성한 영수증을 보험계약자에게 교부하는 경우만 해당)와 제2호의 권한만 있다.","src":"상법 제646조의2③ | 기출 2022-6 | 기출 2024-4"},{"t":"즉 보험료 수령은 보험자가 작성한 영수증을 교부할 때만 가능하고, 보험자가 작성한 증권 교부 권한은 있다.","src":"상법 제646조의2③ | 기출 2023-5 | 기출 2026-4"},{"t":"청약·고지·통지·해지·취소 등 의사표시를 수령할 권한은 없다.","src":"상법 제646조의2③ | 기출 2021-4 | 기출 2023-5 | 기출 2024-4"},{"t":"보험계약의 체결·변경·해지 등 의사표시를 보험계약자에게 할 권한도 없다.","src":"상법 제646조의2③ | 기출 2022-6 | 기출 2023-5"}]},{"머리":"피보험자·보험수익자에게의 적용","줄":[{"t":"피보험자나 보험수익자가 보험료를 지급하거나 보험계약에 관한 의사표시를 할 의무가 있는 경우에는 제1항부터 제3항까지를 그 피보험자나 보험수익자에게도 적용한다.","src":"상법 제646조의2④ | 기출 2025-5"}]}],"함정":[{"x":"보험대리상은 보험계약자에게 보험계약에 관한 해지의 의사표시를 할 수 없다.","o":"보험대리상은 보험계약자에게 체결·변경·해지 등 보험계약에 관한 의사표시를 할 수 있다.","src":"상법 제646조의2①4호 | 기출 2021-4"},{"x":"甲은 자신이 작성한 영수증을 丙에게 교부하는 경우 丙으로부터 보험료를 수령할 권한이 있다.","o":"보험대리상이 아닌 중개자는 「보험자가 작성한」 영수증을 교부하는 경우에만 보험료를 수령할 수 있다(자신이 작성한 영수증은 불가).","src":"상법 제646조의2③ | 기출 2023-5"},{"x":"보험자는 상법에 정해진 보험대리상의 권한을 제한할 수 없다.","o":"보험자는 보험대리상의 권한 중 일부를 제한할 수 있으나, 선의의 보험계약자에게 대항하지 못한다.","src":"상법 제646조의2② | 기출 2025-5"},{"x":"보험자는 보험계약의 해지의 의사표시를 할 수 있는 보험대리상의 권한을 제한할 수 없다.","o":"보험자는 보험대리상의 권한 중 일부(해지 의사표시 권한 포함)를 제한할 수 있으나 선의의 계약자에게 대항하지 못한다.","src":"상법 제646조의2② | 기출 2026-4"}]},"고지의무":{"묶음":[{"머리":"고지의무자와 시기","줄":[{"t":"고지의무자: 보험계약자 또는 피보험자. 보험수익자는 고지의무자가 아니다.","src":"상법 제651조 | 기출 2021-7 | 기출 2023-8 | 기출 2026-8"},{"t":"타인을 위한 손해보험의 타인(피보험자)도 고지의무를 부담한다.","src":"상법 제651조 | 기출 2022-9"},{"t":"고지 시점은 보험계약 당시이다.","src":"상법 제651조"},{"t":"고지 대상은 「중요한 사항」이다. 보험자가 서면으로 질문한 사항은 중요한 사항으로 추정한다(간주·의제 아님).","src":"상법 제651조의2 | 기출 2022-9 | 기출 2023-8 | 기출 2024-6 | 기출 2026-8"},{"t":"보험계약자 대리인이 안 사유는 본인이 안 것과 같다.","src":"상법 제646조"}]},{"머리":"해지권(제651조)","줄":[{"t":"요건: 계약 당시 보험계약자 또는 피보험자가 고의 또는 중대한 과실로 중요한 사항을 고지하지 아니하거나 부실의 고지를 한 때.","src":"상법 제651조 | 기출 2025-9"},{"t":"행사기간: 보험자가 그 사실을 안 날부터 1월 내, 계약을 체결한 날부터 3년 내에 한하여 해지할 수 있다.","src":"상법 제651조 | 기출 2021-7 | 기출 2024-6 | 기출 2026-8"},{"t":"예: 고의 불고지 시 체결일부터 1월 시점에는 해지 가능. 중과실 불고지 시 체결일부터 5년 시점에는 해지 불가(3년 초과).","src":"기출 2021-7"},{"t":"안 날부터 1월이 경과하면 해지할 수 없다.","src":"상법 제651조 | 기출 2022-9"},{"t":"예외: 보험자가 계약 당시 그 사실을 알았거나 중대한 과실로 알지 못한 때에는 해지할 수 없다.","src":"상법 제651조 단서 | 기출 2021-7 | 기출 2025-9"},{"t":"경과실로 불고지·부실고지한 경우에는 해지할 수 없다.","src":"상법 제651조 | 기출 2025-9"}]},{"머리":"해지의 효과","줄":[{"t":"사고 발생 후라도 고지의무 위반을 이유로 해지하면 보험자는 보험금 지급 책임이 없고 이미 지급한 보험금의 반환을 청구할 수 있다.","src":"상법 제655조"},{"t":"다만 고지의무 위반 사실이 보험사고 발생에 영향을 미치지 아니하였음이 증명된 경우에는 보험금을 지급할 책임이 있다.","src":"상법 제655조 단서 | 기출 2021-11 | 기출 2023-8 | 기출 2026-8"},{"t":"인과관계가 없음의 증명 책임은 보험계약자 측에 있다.","src":"상법 제655조 | 기출 2021-10"}]},{"머리":"강행규정성","줄":[{"t":"보험계약자가 과실 없이 중요한 사항을 불고지한 경우에도 해지할 수 있도록 하는 약관은 보험계약자에게 불리한 변경이어서 가계보험에서 허용되지 않는다.","src":"상법 제663조 | 기출 2024-13"},{"t":"보험수익자가 계약 체결 시 고지의무를 부담하도록 하는 약관도 불이익 변경이어서 허용되지 않는다.","src":"상법 제663조 | 기출 2024-13"}]}],"함정":[{"x":"고지의무를 부담하는 자는 보험계약상의 보험계약자 또는 보험수익자이다.","o":"고지의무자는 보험계약자 또는 피보험자이다(보험수익자는 아님).","src":"상법 제651조 | 기출 2021-7"},{"x":"타인을 위한 손해보험계약에서 그 타인은 고지의무를 부담하지 않는다.","o":"타인을 위한 손해보험에서 그 타인(피보험자)도 고지의무를 부담한다.","src":"상법 제651조 | 기출 2022-9"},{"x":"보험자가 서면으로 질문한 사항은 중요한 사항으로 본다.","o":"보험자가 서면으로 질문한 사항은 중요한 사항으로 추정한다(간주 아님).","src":"상법 제651조의2 | 기출 2022-9"},{"x":"고지의무자가 고의 또는 중과실로 중요한 사항을 불고지 또는 부실고지한 경우 보험 자가 계약 당시에 그 사실을 알았을지라도 보험자는 보험계약을 해지할 수 있다.","o":"보험자가 계약 당시 그 사실을 알았거나 중대한 과실로 알지 못한 때에는 해지할 수 없다.","src":"상법 제651조 단서 | 기출 2022-9"},{"x":"보험수익자는 고지의무를 부담한다.","o":"보험수익자는 고지의무자가 아니다(고지의무자는 보험계약자 또는 피보험자).","src":"상법 제651조 | 기출 2023-8"},{"x":"보험계약당시에 고지의무와 관련 보험자가 서면으로 질문한 사항은 중요한 사항으로 의제한다.","o":"보험자가 서면으로 질문한 사항은 중요한 사항으로 추정한다(의제 아님).","src":"상법 제651조의2 | 기출 2023-8"},{"x":"고지의무자의 고지의무 위반을 이유로 보험자가 계약을 해지한 경우 보험자는 이미 받은 보험료의 전부를 반환하여야 한다.","o":"고지의무 위반으로 인한 해지 시 이미 받은 보험료의 전부 반환 의무를 상법은 규정하지 않는다(출제 오답, 바른 처리 미확인).","src":"보충(추정) | 기출 2023-8"},{"x":"보험계약 당시에 피보험자가 경과실로 인하여 중요한 사항에 대하여 부실의 고지를 한 경우 보험자는 계약을 해지할 수 있다.","o":"해지 사유는 계약자 또는 피보험자의 고의 또는 중대한 과실이고, 경과실로는 해지할 수 없다.","src":"상법 제651조 | 기출 2025-9"},{"x":"보험계약당시에 피보험자가 중대한 과실로 인하여 중요한 사항을 고지하지 아니한 때 에는 보험자는 그 사실을 안 날로부터 1년이 지난 후 계약을 해지할 수 있다.","o":"고의 또는 중과실 불고지·부실고지 시 보험자는 안 날부터 1월 내, 체결일부터 3년 내에 해지할 수 있다(1년 후 해지 불가).","src":"상법 제651조 | 기출 2026-8"}]},"위험변경ㆍ증가":{"묶음":[{"머리":"위험 변경·증가의 의미","줄":[{"t":"사고발생의 위험이 현저하게 변경 또는 증가된 사실이란, 그 변경·증가된 위험이 계약 체결 당시 존재했다면 보험자가 계약을 체결하지 않았거나 적어도 그 보험료로는 인수하지 않았을 것으로 인정되는 정도를 말한다.","src":"기출 2021-9 | 기출 2021-10"},{"t":"위험 변경·증가의 통지의무는 보험기간 중에 발생한다. 계약 체결 직전에 안 사실은 고지의무의 문제이다.","src":"상법 제652조① | 기출 2021-9"}]},{"머리":"통지의무(제652조)","줄":[{"t":"통지의무자: 보험계약자 또는 피보험자. 보험수익자는 통지의무자가 아니다.","src":"상법 제652조① | 기출 2022-10 | 기출 2023-15 | 기출 2024-9 | 기출 2026-9"},{"t":"타인을 위한 손해보험의 타인(피보험자)도 통지의무를 진다.","src":"상법 제652조① | 기출 2024-9"},{"t":"위험이 현저하게 변경 또는 증가된 사실을 안 때 지체없이 보험자에게 통지하여야 한다.","src":"상법 제652조① | 기출 2021-9 | 기출 2025-10"},{"t":"통지를 해태한 때 보험자는 그 사실을 안 날부터 1월 내에 한하여 계약을 해지할 수 있다.","src":"상법 제652조① | 기출 2023-15 | 기출 2024-9"},{"t":"보험자가 통지를 받은 때에는 1월 내에 보험료의 증액을 청구하거나 계약을 해지할 수 있다(통지를 받은 날로부터 1월, 2월 경과하면 해지 불가).","src":"상법 제652조② | 기출 2022-10 | 기출 2023-15 | 기출 2024-9 | 기출 2025-10 | 기출 2026-9"}]},{"머리":"계약자 등의 고의·중과실로 인한 위험 변경·증가(제653조)","줄":[{"t":"보험기간 중 보험계약자, 피보험자 또는 보험수익자의 고의 또는 중대한 과실로 사고발생의 위험이 현저하게 변경 또는 증가된 때 보험자는 그 사실을 안 날부터 1월 내에 보험료의 증액을 청구하거나 계약을 해지할 수 있다.","src":"상법 제653조 | 기출 2021-10 | 기출 2022-10 | 기출 2024-9 | 기출 2025-10"},{"t":"이 경우 주체에는 보험수익자가 포함된다(통지의무와 다름).","src":"상법 제653조 | 기출 2022-10 | 기출 2023-15"},{"t":"해지와 증액은 보험자가 선택한다(증액만 가능하다거나 해지만 가능하다는 말은 틀림).","src":"상법 제653조 | 기출 2024-9"},{"t":"해지는 의사표시로 하는 것이지 당연히 해지된 것으로 보지 않는다.","src":"상법 제653조 | 기출 2026-9"}]},{"머리":"해지의 효과(제655조)","줄":[{"t":"위험변경증가 통지를 받지 못했음을 이유로 유효하게 해지한 경우, 변경·증가 사실이 사고 발생에 영향을 미쳤다면 보험자는 보험금을 지급할 책임이 없다.","src":"상법 제655조 | 기출 2024-10"},{"t":"이미 지급한 보험금의 반환도 청구할 수 있다.","src":"상법 제655조 | 기출 2022-11"},{"t":"변경·증가된 사실이 사고 발생에 영향을 미치지 아니하였음이 증명되면 보험금을 지급할 책임이 있다.","src":"상법 제655조 단서 | 기출 2021-11"},{"t":"보험자가 위험 변경을 이유로 해지하려면 그 사실을 입증하여야 한다.","src":"기출 2022-11"}]}],"함정":[{"x":"보험계약체결 직전에 보험계약자가 사고발생의 위험이 변경 또는 증가된 사실을 안 때에는 지체없이 보험자에게 통지하여야 한다.","o":"위험 변경·증가의 통지의무는 보험기간 중에 보험계약자 또는 피보험자가 그 사실을 안 때에 발생한다(체결 직전 아님).","src":"상법 제652조① | 기출 2021-9"},{"x":"보험기간 중에 위험변경증가의 통지를 받은 때에는 보험자는 3개월 내에 보험료의 증액을 청구할 수 있다.","o":"통지를 받은 보험자는 1월 내에 보험료의 증액을 청구하거나 계약을 해지할 수 있다(3월 아님).","src":"상법 제652조② | 기출 2021-9"},{"x":"보험기간 중에 위험변경증가의 통지를 받은 때에는 보험자는 3개월 내에 계약을 해지 할 수 있다.","o":"통지를 받은 보험자는 1월 내에 보험료의 증액을 청구하거나 계약을 해지할 수 있다(3월 아님).","src":"상법 제652조② | 기출 2021-9"},{"x":"위험의 현저한 변경이나 증가된 사실과 보험사고 발생과의 사이에 인과관계가 부존재 한다는 점에 관한 주장ㆍ입증책임은 보험자 측에 있다.","o":"위험 변경·증가와 사고 발생 사이에 인과관계가 없음의 증명은 보험계약자 측이 한다(제655조 단서의 「증명된 경우」).","src":"상법 제655조 | 기출 2021-10"},{"x":"보험수익자가 사고발생의 위험이 현저하게 변경된 사실을 안 때에는 지체없이 보험자 에게 통지하여야 한다.","o":"위험 변경·증가의 통지의무자는 보험계약자 또는 피보험자이다(보험수익자는 아님).","src":"상법 제652조① | 기출 2023-15"},{"x":"통지의무자가 사고발생의 위험이 현저하게 증가된 사실의 통지를 해태한 때에는 보험자는 그 사실을 안 날부터 3월내에 한하여 계약을 해지할 수 있다.","o":"통지를 해태한 때 보험자는 그 사실을 안 날부터 1월 내에 한하여 해지할 수 있다(3월 아님).","src":"상법 제652조① | 기출 2023-15"},{"x":"보험수익자의 중대한 과실로 인하여 사고발생의 위험이 현저하게 증가된 때에는 보험자는 그 사실을 안 날부터 2월내에 계약을 해지할 수 있다.","o":"보험수익자의 중대한 과실로 위험이 현저히 증가된 때 보험자는 안 날부터 1월 내에 증액 청구 또는 해지할 수 있다(2월 아님).","src":"상법 제653조 | 기출 2023-15"},{"x":"보험수익자의 고의로 인하여 사고 발생의 위험이 현저하게 증가된 때에는 보험자는 그 사실을 안 날로부터 1월내에 보험계약을 해지할 수 있을 뿐이고, 보험료의 증액을 청구할 수는 없다.","o":"보험수익자의 고의로 위험이 현저히 증가된 때 보험자는 안 날부터 1월 내에 보험료 증액을 청구하거나 계약을 해지할 수 있다(둘 중 선택).","src":"상법 제653조 | 기출 2024-9"},{"x":"보험계약자가 지체없이 위험변경증가의 통지를 한 때에는 보험자는 1월내에 보험료 증액을 청구할 수 있을 뿐이고 보험계약을 해지할 수는 없다.","o":"통지를 받은 보험자는 1월 내에 보험료 증액 청구 또는 계약 해지 중 선택할 수 있다.","src":"상법 제652조② | 기출 2024-9"},{"x":"타인을 위한 손해보험의 타인이 사고발생 위험이 현저하게 변경 또는 증가된 사실을 알게된 경우 이를 보험자에게 통지할 의무는 없다.","o":"타인(피보험자)도 위험 변경·증가를 안 때에는 지체없이 보험자에게 통지할 의무가 있다.","src":"상법 제652조① | 기출 2024-9"},{"x":"피보험자의 중대한 과실로 인하여 사고발생의 위험이 현저하게 증가된 때에는 보험자는 그 사실을 안 날부터 3월내에 계약을 해지할 수 있다.","o":"피보험자의 중대한 과실로 위험이 현저히 증가된 때 보험자는 안 날부터 1월 내에 증액 청구 또는 해지할 수 있다(3월 아님).","src":"상법 제653조 | 기출 2025-10"},{"x":"보험계약자가 위험이 증가된 사실을 안 때에는 보험자에게 통지할 의무가 없다.","o":"보험기간 중 위험 변경·증가 사실을 안 보험계약자·피보험자는 지체없이 보험자에게 통지하여야 한다.","src":"상법 제652조① | 기출 2026-9"},{"x":"보험계약자의 중과실로 인하여 위험이 증가된 때에는 보험자는 계약을 해지할 수 없 다.","o":"계약자 등의 중대한 과실로 위험이 현저히 증가된 때 보험자는 안 날부터 1월 내에 증액 청구 또는 해지할 수 있다.","src":"상법 제653조 | 기출 2026-9"},{"x":"피보험자의 고의로 인하여 위험이 증가된 때에는 계약은 해지된 것으로 본다.","o":"고의로 위험이 증가된 때 보험자는 안 날부터 1월 내에 증액을 청구하거나 해지「할 수 있다」(자동 해지 아님).","src":"상법 제653조 | 기출 2026-9"}]},"보험료의 지급과 지체ㆍ부활":{"묶음":[{"머리":"보험료 지급 의무와 책임 개시","줄":[{"t":"보험계약자는 계약 체결 후 지체없이 보험료의 전부 또는 제1회 보험료를 지급하여야 한다.","src":"상법 제650조① | 기출 2021-6"},{"t":"보험자의 책임은 다른 약정이 없으면 최초의 보험료를 지급받은 때로부터 개시한다.","src":"상법 제656조 | 기출 2024-10"}]},{"머리":"제1회 보험료 미지급","줄":[{"t":"지급하지 아니하는 경우 다른 약정이 없는 한 계약성립 후 2월이 경과하면 그 계약은 해제된 것으로 본다(별도 해제 의사표시 불요).","src":"상법 제650조① | 기출 2022-6 | 기출 2024-5 | 기출 2025-7"}]},{"머리":"계속보험료 미지급","줄":[{"t":"약정한 시기에 지급되지 아니하면 보험자는 상당한 기간을 정하여 보험계약자에게 최고하고, 그 기간 내에 지급되지 아니한 때 계약을 해지할 수 있다. 최고 없이 즉시 해지할 수 없고, 「해지된 것으로 본다」도 아님.","src":"상법 제650조② | 기출 2022-6 | 기출 2023-6 | 기출 2025-7"},{"t":"사고 발생 후라도 이 해지를 하면 보험자는 보험금 지급 책임이 없다.","src":"상법 제655조 | 기출 2021-11 | 기출 2026-7"},{"t":"특정한 타인을 위한 보험에서 보험계약자가 지체한 때 보험자는 그 타인에게도 상당한 기간을 정하여 최고한 후가 아니면 계약을 해제 또는 해지하지 못한다.","src":"상법 제650조③ | 기출 2023-6 | 기출 2026-7"}]},{"머리":"부활(제650조의2)","줄":[{"t":"요건: 제650조제2항에 따라 보험계약이 해지되고 해지환급금이 지급되지 아니한 경우.","src":"상법 제650조의2 | 기출 2022-8 | 기출 2025-8"},{"t":"절차: 일정한 기간 내에 연체보험료에 약정이자를 붙여 보험자에게 지급하고 부활을 청구한다.","src":"상법 제650조의2 | 기출 2022-8"},{"t":"제638조의2가 준용되므로 보험자는 30일 내 낙부 통지를 발송하여야 하고 해태하면 승낙한 것으로 본다.","src":"상법 제650조의2 | 기출 2022-8"},{"t":"부활할 수 없는 경우: 제1회 보험료 미지급으로 해제된 경우, 고지의무 위반·위험변경·위험증가로 해지된 경우, 해지환급금이 지급된 경우.","src":"상법 제650조의2 | 기출 2022-8 | 기출 2023-7 | 기출 2025-8"},{"t":"부활이 가능한 경우는 계속보험료 연체로 인한 해지뿐이다(2023 기출 정답 1개).","src":"기출 2023-7"}]},{"머리":"보험료의 감액·반환","줄":[{"t":"특별한 위험을 예기하여 보험료를 정한 경우 그 위험이 보험기간 중 소멸하면 보험계약자는 그 후의 보험료 감액을 청구할 수 있다.","src":"상법 제647조 | 기출 2024-5 | 기출 2025-6"},{"t":"계약의 전부 또는 일부가 무효인 경우 보험계약자와 피보험자가 선의이며 중대한 과실이 없으면 보험료의 전부 또는 일부의 반환을 청구할 수 있다. 보험계약자와 보험수익자가 선의이며 중대한 과실이 없는 때에도 같다.","src":"상법 제648조 | 기출 2024-5 | 기출 2025-6 | 기출 2026-5"},{"t":"사고 발생 전 임의해지 시 다른 약정이 없으면 미경과보험료의 반환을 청구할 수 있다.","src":"상법 제649조③ | 기출 2023-6 | 기출 2025-6"},{"t":"초과보험의 보험료 감액은 장래에 대하여서만 효력이 있다.","src":"상법 제669조①"}]},{"머리":"보험료 관련 시효","줄":[{"t":"보험료청구권 2년, 보험료 또는 적립금의 반환청구권 3년.","src":"상법 제662조"}]}],"함정":[{"x":"계속보험료가 약정한 시기에 지급되지 아니한 때에는 보험자는 상당한 기간을 정하여 보험계약자에게 최고하고 그 기간내에 지급되지 아니한 때에는 그 계약은 해지된 것 으로 본다.","o":"계속보험료가 약정한 시기에 지급되지 아니하면 보험자는 상당한 기간을 정하여 최고하고, 그 기간 내에 지급되지 아니한 때 계약을 해지할 수 있다(해지된 것으로 보는 것이 아님).","src":"상법 제650조② | 기출 2021-6"},{"x":"특정한 타인을 위한 보험의 경우에 보험계약자가 보험료의 지급을 지체한 때에는 보험자는 그 계약을 해제 또는 해지할 수 있다.","o":"특정한 타인을 위한 보험에서 계약자가 보험료 지급을 지체한 때에는 보험자는 그 타인에게도 상당한 기간을 정하여 최고한 후가 아니면 계약을 해제 또는 해지하지 못한다.","src":"상법 제650조③ | 기출 2021-6"},{"x":"보험계약자가 최초보험료를 지급하지 아니한 경우에는 다른 약정이 없는 한 계약성립 후 1월이 경과하면 그 계약은 해제된 것으로 본다.","o":"제1회 보험료를 지급하지 아니하면 다른 약정이 없는 한 계약성립 후 2월이 경과한 때 계약은 해제된 것으로 본다.","src":"상법 제650조① | 기출 2021-6"},{"x":"계속보험료가 연체된 경우 보험대리상이 아니면서 특정한 보험자를 위하여 계속적으로 보험계약의 체결을 중개하는 자는 보험계약자에 대해 해지의 의사표시를 할 수 있는 권한이 있다.","o":"보험대리상이 아닌 중개자는 보험료 수령(보험자 작성 영수증 교부 시)과 증권 교부 권한만 있고, 해지 의사표시 권한은 없다.","src":"상법 제646조의2③ | 기출 2022-6"},{"x":"제1회 보험료의 지급이 이루어지지 않아 보험계약이 해제된 경우 보험계약자는 보험 계약의 부활을 청구할 수 있다.","o":"부활은 제650조제2항에 따라 계속보험료 연체로 해지되고 해지환급금이 지급되지 않은 경우에만 청구할 수 있다(제1회 보험료 미지급 해제는 부활 불가).","src":"상법 제650조의2 | 기출 2022-8"},{"x":"보험사고가 발생하기 전에 보험계약자가 계약을 해지한 경우 당사자간에 약정을 한 경우에 한해 보험계약자는 미경과보험료의 반환을 청구할 수 있다.","o":"사고 발생 전 해지한 경우 다른 약정이 없으면 미경과보험료의 반환을 청구할 수 있다.","src":"상법 제649조③ | 기출 2023-6"},{"x":"보험계약자가 계약체결후 제1회 보험료를 지급하지 아니하는 경우 다른 약정이 없는 한 보험자가 계약성립후 2월이내에 그 계약을 해제하지 않으면 그 계약은 존속한다.","o":"제1회 보험료 미지급 시 다른 약정이 없는 한 계약성립 후 2월이 경과하면 별도의 해제 의사표시 없이 해제된 것으로 본다.","src":"상법 제650조① | 기출 2023-6"},{"x":"계속보험료가 약정한 시기에 지급되지 아니한 때에는 보험자는 보험계약자에 대하여 최고 없이 그 계약을 해지할 수 있다.","o":"계속보험료 미지급 시 보험자는 상당한 기간을 정해 최고하고, 그 기간 내에 지급되지 아니한 때 해지할 수 있다(최고 없는 해지 불가).","src":"상법 제650조② | 기출 2023-6"},{"x":"보험계약의 일부가 무효인 경우에 보험계약자와 피보험자가 선의이며 중대한 과실이 없는 때에도 보험자에 대하여 보험료의 일부의 반환을 청구할 수 없다.","o":"일부 무효인 경우에도 계약자와 피보험자가 선의이며 중대한 과실이 없으면 보험료의 일부 반환을 청구할 수 있다.","src":"상법 제648조 | 기출 2025-6"},{"x":"보험계약의 전부가 무효인 경우에 보험계약자와 보험수익자가 선의이며 중대한 과실 이 없는 때에도 보험자에 대하여 보험료의 반환을 청구할 수 없다.","o":"전부 무효인 경우에도 계약자와 수익자가 선의이며 중대한 과실이 없으면 보험료 반환을 청구할 수 있다.","src":"상법 제648조 | 기출 2025-6"},{"x":"보험사고가 발생하기 전에 보험계약자가 보험계약의 전부를 해지한 경우에도 보험 계약자는 당사자간에 다른 약정이 없으면 미경과보험료의 반환을 청구할 수 없다.","o":"사고 발생 전 전부 해지한 경우 다른 약정이 없으면 미경과보험료 반환을 청구할 수 있다.","src":"상법 제649조③ | 기출 2025-6"},{"x":"계속보험료가 약정한 시기에 지급되지 아니한 때에는 보험자는 바로 그 계약을 해지할 수 있다.","o":"계속보험료 미지급 시 보험자는 바로 해지할 수 없고 상당한 기간을 정한 최고 후 해지할 수 있다.","src":"상법 제650조② | 기출 2025-7"},{"x":"타인을 위한 보험의 경우에 보험계약자가 보험료의 지급을 지체한 때에 보험자가 계약을 해지하기 위해서 그 타인에게 보험료 지급을 최고할 필요는 없다.","o":"특정한 타인을 위한 보험에서 계약자가 지체한 때 보험자는 그 타인에게도 최고한 후가 아니면 해제·해지하지 못한다.","src":"상법 제650조③ | 기출 2025-7"},{"x":"보험자의 책임은 당사자간에 다른 약정이 없으면 보험계약자의 보험료 지급 여부에 관계없이 계약이 성립한 때부터 개시한다.","o":"보험자의 책임은 다른 약정이 없으면 최초 보험료를 지급받은 때부터 개시한다.","src":"상법 제656조 | 기출 2025-7"},{"x":"보험계약의 해지 사유에 관계없이 보험계약자는 보험계약의 부활을 청구할 수 있다.","o":"부활은 계속보험료 연체로 해지되고 해지환급금이 지급되지 아니한 경우에만 청구할 수 있다.","src":"상법 제650조의2 | 기출 2025-8"},{"x":"보험계약이 해지된 후 보험계약자가 해지환급금을 지급받은 뒤에도 해지환급금을 반환한다면 부활을 청구할 수 있다.","o":"해지환급금이 지급된 후에는 반환하더라도 부활을 청구할 수 없다(요건이 「해지환급금이 지급되지 아니한 경우」).","src":"상법 제650조의2 | 기출 2025-8"},{"x":"보험계약자가 계약의 부활을 청구하는 경우 보험자는 이를 승낙하여야 한다.","o":"부활 청구에는 제638조의2가 준용되어 보험자는 30일 내 낙부 통지를 발송하여야 하고 해태하면 승낙한 것으로 본다(승낙 의무 규정 아님).","src":"상법 제650조의2 | 기출 2025-8"},{"x":"보험계약자가 계약체결후 지체없이 제1회 보험료를 지급하지 아니하는 경우에는 다른 약정이 없는 한 계약성립후 15일이 경과하면 그 계약은 해제된 것으로 본다.","o":"제1회 보험료를 지급하지 아니하면 다른 약정이 없는 한 계약성립 후 2월이 경과한 때 해제된 것으로 본다(15일 아님).","src":"상법 제650조① | 기출 2026-7"},{"x":"계속보험료가 약정한 시기에 지급되지 아니한 때에는 보험자는 상당한 기간을 정하여 보험계약자에게 최고하고 그 기간내에 지급되지 아니한 때에는 그 계약을 취소할 수 있다.","o":"계속보험료 미지급 시 최고 후 기간 내에 지급되지 않으면 보험자는 계약을 해지할 수 있다(취소 아님).","src":"상법 제650조② | 기출 2026-7"},{"x":"보험사고가 발생한 후에 보험자가 계속보험료 미지급을 이유로 계약을 해지하였을 때 에는 보험금을 지급할 책임이 있다.","o":"사고 발생 후라도 계속보험료 미지급을 이유로 보험자가 해지하면 보험금을 지급할 책임이 없고 이미 지급한 보험금의 반환을 청구할 수 있다.","src":"상법 제655조 | 기출 2026-7"}]},"보험계약의 무효ㆍ해지":{"묶음":[{"머리":"무효 사유","줄":[{"t":"보험사고가 이미 발생하였거나 발생할 수 없는 것인 때(당사자 쌍방과 피보험자가 이를 알지 못한 때 제외).","src":"상법 제644조"},{"t":"보험계약자의 사기로 체결된 초과보험.","src":"상법 제669조④ | 기출 2025-15 | 기출 2026-14"},{"t":"보험계약자의 사기로 체결된 중복보험.","src":"상법 제672조③ | 기출 2024-17 | 기출 2026-17"},{"t":"무효의 효과: 보험계약자와 피보험자(또는 수익자)가 선의·무중과실이면 보험료 반환 청구 가능.","src":"상법 제648조"},{"t":"사기에 의한 초과·중복보험이 무효이면 보험자는 그 사실을 안 때까지의 보험료를 청구할 수 있고 보험금 지급 의무는 없다.","src":"상법 제669조④ | 기출 2026-17"}]},{"머리":"해지 사유 한눈에","줄":[{"t":"보험계약자의 임의해지: 사고 발생 전(제649조).","src":"상법 제649조"},{"t":"계속보험료 미지급: 최고 후 해지(제650조②).","src":"상법 제650조②"},{"t":"고지의무 위반: 안 날부터 1월, 체결일부터 3년(제651조).","src":"상법 제651조"},{"t":"위험 변경·증가 통지 해태 또는 통지 후: 1월(제652조).","src":"상법 제652조"},{"t":"계약자 등의 고의·중과실로 위험 증가: 안 날부터 1월(제653조).","src":"상법 제653조"},{"t":"보험자의 파산선고: 보험계약자가 해지 가능(제654조①).","src":"상법 제654조①"}]},{"머리":"보험자의 파산(제654조)","줄":[{"t":"보험자가 파산의 선고를 받은 때에는 보험계약자는 계약을 해지할 수 있다.","src":"상법 제654조① | 기출 2022-11 | 기출 2023-16 | 기출 2026-6"},{"t":"해지하지 아니한 보험계약은 파산선고 후 3월을 경과한 때 그 효력을 잃는다.","src":"상법 제654조② | 기출 2022-11 | 기출 2023-16 | 기출 2024-11"}]},{"머리":"임의해지(제649조)","줄":[{"t":"사고 발생 전에는 보험계약자가 언제든지 계약의 전부 또는 일부를 해지할 수 있다.","src":"상법 제649조① | 기출 2021-5 | 기출 2026-6"},{"t":"타인을 위한 보험은 타인의 동의를 얻지 아니하거나 보험증권을 소지하지 아니하면 해지하지 못한다.","src":"상법 제649조① 단서 | 기출 2021-5 | 기출 2022-7"},{"t":"사고 발생 후에도 보험금액이 감액되지 아니하는 보험은 보험계약자가 해지할 수 있다.","src":"상법 제649조② | 기출 2021-5 | 기출 2024-7"},{"t":"해지 시 다른 약정이 없으면 미경과보험료 반환 청구 가능.","src":"상법 제649조③ | 기출 2024-7 | 기출 2026-6"}]},{"머리":"해지의 효과(제655조)","줄":[{"t":"사고 발생 후라도 제650조·651조·652조·653조에 따라 해지하면 보험자는 보험금 지급 책임이 없고 이미 지급한 보험금의 반환을 청구할 수 있다.","src":"상법 제655조"},{"t":"다만 고지의무 위반 또는 위험 변경·증가가 사고 발생에 영향을 미치지 아니하였음이 증명되면 보험금을 지급할 책임이 있다. (제650조 계속보험료 미지급 해지에는 이 단서가 없다.)","src":"상법 제655조 | 기출 2021-11"}]}],"함정":[{"x":"보험계약자가 보험계약을 전부 해지했을 때에는 언제든지 미경과보험료의 반환을 청 구할 수 있다.","o":"사고 발생 전 임의해지(제649조제1항)의 경우에 한하여, 다른 약정이 없으면 미경과보험료의 반환을 청구할 수 있다.","src":"상법 제649조③ | 기출 2021-5"},{"x":"보험계약 당시에 보험사고가 이미 발생하였음을 A와 B가 알았을지라도 C가 알지 못했다면 그 계약은 유효하다.","o":"보험사고가 이미 발생한 경우 당사자 쌍방과 피보험자 모두 알지 못한 때에만 유효하므로, 일부라도 알았으면 무효이다.","src":"상법 제644조 | 기출 2022-4"},{"x":"보험자가 보험기간 중에 사고발생의 위험이 현저하게 증가하여 보험계약을 해지한 경우 이미 지급한 보험금의 반환을 청구할 수 없다.","o":"위험 증가를 이유로 해지한 경우 보험자는 이미 지급한 보험금의 반환을 청구할 수 있다(영향 없음이 증명된 경우 제외).","src":"상법 제655조 | 기출 2022-11"},{"x":"보험수익자는 보험사고의 발생을 안 때에는 지체없이 보험계약자에게 그 통지를 발송 하여야 한다.","o":"보험수익자의 사고 발생 통지의 상대방은 보험자이다.","src":"상법 제657조① | 기출 2023-16"},{"x":"보험자가 파산의 선고를 받은 때에는 보험계약자는 계약을 해지할 수 없다.","o":"보험자가 파산선고를 받은 때에는 보험계약자는 계약을 해지할 수 있다.","src":"상법 제654조① | 기출 2026-6"},{"x":"타인을 위한 보험계약의 경우에는 보험계약자는 그 타인의 동의를 얻고 보험증권을 소지한 때에만 계약을 해지할 수 있다.","o":"타인을 위한 보험은 타인의 동의를 얻지 아니하거나 보험증권을 소지하지 아니하면 해지하지 못한다(출제 오답 표현 차이로 추정, 법문 기준).","src":"상법 제649조① | 기출 2026-6"},{"x":"보험계약을 임의해지한 경우 보험계약자는 당사자간에 다른 약정이 없으면 미경과 보험료의 반환을 청구할 수 없다.","o":"임의해지(사고 발생 전)한 보험계약자는 다른 약정이 없으면 미경과보험료의 반환을 청구할 수 있다.","src":"상법 제649조③ | 기출 2026-6"}]},"보험자의 면책사유":{"묶음":[{"머리":"보험계약자 등의 고의·중과실(제659조)","줄":[{"t":"보험사고가 보험계약자 또는 피보험자나 보험수익자의 고의 또는 중대한 과실로 인하여 생긴 때에는 보험자는 보험금액을 지급할 책임이 없다.","src":"상법 제659조① | 기출 2023-13 | 기출 2024-11 | 기출 2025-12 | 기출 2026-10"},{"t":"경과실만으로는 면책되지 않는다(계약자·피보험자·수익자 모두 동일).","src":"상법 제659조① | 기출 2025-12 | 기출 2026-18"}]},{"머리":"전쟁 기타의 변란(제660조)","줄":[{"t":"보험사고가 전쟁 기타의 변란으로 인하여 생긴 때에는 당사자 간에 다른 약정이 없으면 보험자는 보험금액을 지급할 책임이 없다.","src":"상법 제660조 | 기출 2023-13 | 기출 2026-10"}]},{"머리":"보험의 목적의 성질·하자·자연소모(제678조)","줄":[{"t":"보험의 목적의 성질, 하자 또는 자연소모로 인한 손해는 보험자가 보상할 책임이 없다.","src":"상법 제678조 | 기출 2021-21 | 기출 2022-22 | 기출 2023-20 | 기출 2024-18 | 기출 2026-18"}]},{"머리":"그 밖의 책임 제한","줄":[{"t":"통지의무 해태로 손해가 증가된 때에는 그 증가된 손해만 보상 책임이 없다.","src":"상법 제657조② | 기출 2021-12 | 기출 2023-16 | 기출 2025-11"},{"t":"사고 발생 후 목적이 보험자 부담 외 사고로 멸실되어도 이미 생긴 손해는 보상 책임을 면하지 못한다(면책 아님).","src":"상법 제675조 | 기출 2021-21 | 기출 2022-20 | 기출 2024-18"},{"t":"연소 작용이 아닌 열의 작용으로 생긴 손해는 화재보험에서 보상하지 않는다.","src":"기출 2023-24"}]}],"함정":[{"x":"보험자가 지급할 보험금액을 정하면 그 정하여진 날부터 1개월 내에 보험금액을 지급 하여야 한다.","o":"약정기간이 없으면 정하여진 날부터 10일 내에 지급하여야 한다(1개월 아님).","src":"상법 제658조 | 기출 2025-12"},{"x":"손해보험계약에서 보험사고가 보험계약자의 경과실로 인하여 생긴 때에는 보험자는 보험금액을 지급할 책임이 없다.","o":"보험자 면책은 고의 또는 중대한 과실인 경우이고, 계약자의 경과실만으로는 면책되지 않는다.","src":"상법 제659조① | 기출 2025-12"},{"x":"손해보험계약에서 보험사고가 보험수익자의 경과실로 인하여 생긴 때에는 보험자는 보험금액을 지급할 책임이 없다.","o":"보험자 면책은 고의 또는 중대한 과실인 경우이고, 수익자의 경과실만으로는 면책되지 않는다.","src":"상법 제659조① | 기출 2025-12"}]},"재보험":{"묶음":[{"머리":"재보험의 정의와 성질","줄":[{"t":"재보험: 보험자가 보험사고로 인하여 부담할 책임에 대하여 다른 보험자와 체결하는 보험계약.","src":"상법 제661조 | 기출 2021-23 | 기출 2023-21 | 기출 2025-24 | 기출 2026-16"},{"t":"원보험계약에 영향을 미치지 아니한다.","src":"상법 제661조 후단 | 기출 2026-16"},{"t":"재보험은 보험자가 인수한 위험을 재보험자에게 분산시키는 제도이다.","src":"기출 2026-16"},{"t":"상법은 재보험을 물건보험의 일종이라고 규정하지 않는다.","src":"상법 제661조 | 기출 2026-16"}]},{"머리":"불이익변경금지 배제","줄":[{"t":"재보험은 특약으로 상법 보험편 규정을 보험계약자의 불이익으로 변경할 수 있다(제663조 단서).","src":"상법 제663조 단서 | 기출 2021-16 | 기출 2022-13 | 기출 2023-14 | 기출 2026-12"},{"t":"해상보험 기타 이와 유사한 보험도 같다.","src":"상법 제663조 단서 | 기출 2021-16 | 기출 2023-14"}]},{"머리":"보험자대위","줄":[{"t":"재보험에도 제3자에 대한 보험자대위가 적용된다.","src":"기출 2021-22"}]}],"함정":[{"x":"상법은 재보험이 물건보험의 일종이라고 규정하고 있다.","o":"상법은 재보험을 물건보험의 일종으로 규정하지 않는다(재보험 체결 가능과 원보험계약에 영향 없음만 규정).","src":"상법 제661조 | 기출 2026-16"}]},"소멸시효ㆍ보험계약자 등의 불이익변경금지":{"묶음":[{"머리":"소멸시효(제662조)","줄":[{"t":"보험금청구권: 3년","src":"상법 제662조 | 기출 2021-15 | 기출 2022-17 | 기출 2023-9 | 기출 2025-13 | 기출 2026-11"},{"t":"보험료 또는 적립금의 반환청구권: 3년","src":"상법 제662조 | 기출 2021-15 | 기출 2022-17 | 기출 2023-9 | 기출 2025-13 | 기출 2026-11"},{"t":"보험료청구권: 2년","src":"상법 제662조 | 기출 2021-15 | 기출 2022-17 | 기출 2024-12 | 기출 2025-13 | 기출 2026-11"},{"t":"합산 문제: 3+3+2 = 8. (2025 기출 정답 8)","src":"기출 2025-13"}]},{"머리":"불이익변경금지(제663조)","줄":[{"t":"이 편의 규정은 당사자 간의 특약으로 보험계약자 또는 피보험자나 보험수익자의 불이익으로 변경하지 못한다.","src":"상법 제663조 | 기출 2021-16 | 기출 2023-14"},{"t":"이익으로의 변경은 가능하다(약관으로도).","src":"상법 제663조 | 기출 2022-13"},{"t":"예외: 재보험 및 해상보험 기타 이와 유사한 보험의 경우에는 불이익 변경도 가능하다.","src":"상법 제663조 단서 | 기출 2021-16 | 기출 2022-13 | 기출 2023-14 | 기출 2026-12"},{"t":"보험계약자와 보험자가 대등한 경제적 지위에서 계약조건을 정하는 기업보험에서는 불이익변경금지 원칙의 적용이 배제된다.","src":"기출 2022-13"},{"t":"가계보험·생명보험은 보험수익자의 불이익으로 변경하지 못한다.","src":"상법 제663조 | 기출 2026-12"}]},{"머리":"약관 사례(가계보험 2024 기출)","줄":[{"t":"과실 없이 중요한 사항을 불고지한 경우에도 해지권을 인정하는 약관: 위반(불리).","src":"상법 제663조 | 기출 2024-13"},{"t":"보험료청구권(보험자의 권리) 소멸시효를 단축하는 약관은 보험계약자에게 불리하지 않아 위반이 아닌 것으로 출제됨.","src":"기출 2024-13"},{"t":"보험수익자에게 고지의무를 부담시키는 약관: 위반.","src":"기출 2024-13"},{"t":"사고 발생 전이지만 일정 기간 계약자의 해지를 금지하는 약관: 위반.","src":"상법 제649조① | 기출 2024-13"}]},{"머리":"준용","줄":[{"t":"이 편의 규정은 그 성질에 반하지 아니하는 범위에서 상호보험, 공제, 그 밖에 이에 준하는 계약에 준용한다.","src":"상법 제664조 | 기출 2022-13"}]}],"함정":[{"x":"보험금청구권은 2년간 행사하지 아니하면 시효의 완성으로 소멸한다.","o":"보험금청구권의 소멸시효는 3년이다.","src":"상법 제662조 | 기출 2021-15"},{"x":"보험료청구권은 1년간 행사하지 아니하면 시효의 완성으로 소멸한다.","o":"보험료청구권의 소멸시효는 2년이다.","src":"상법 제662조 | 기출 2021-15"},{"x":"적립금의 반환청구권은 2년간 행사하지 아니하면 시효의 완성으로 소멸한다.","o":"보험료 또는 적립금의 반환청구권의 소멸시효는 3년이다.","src":"상법 제662조 | 기출 2021-15"},{"x":"상법 보험편의 규정은 당사자간의 특약으로 피보험자의 이익으로 변경하지 못한다.","o":"상법 보험편의 규정은 특약으로 피보험자의 불이익으로 변경하지 못한다(이익으로의 변경은 가능).","src":"상법 제663조 | 기출 2021-16"},{"x":"재보험의 경우 상법 규정을 보험계약자의 불이익으로 변경할 수 없다.","o":"재보험은 특약으로 보험계약자의 불이익으로 변경할 수 있다.","src":"상법 제663조 단서 | 기출 2026-12"},{"x":"해상보험의 경우 상법 규정을 피보험자의 불이익으로 변경할 수 없다.","o":"해상보험은 특약으로 피보험자의 불이익으로 변경할 수 있다.","src":"상법 제663조 단서 | 기출 2026-12"},{"x":"생명보험의 경우 상법 규정을 보험수익자의 불이익으로 변경할 수 있다.","o":"생명보험(가계보험)은 특약으로 보험수익자의 불이익으로 변경할 수 없다.","src":"상법 제663조 | 기출 2026-12"}]},"손해보험계약의 의의와 피보험이익":{"묶음":[{"머리":"보험자의 책임","줄":[{"t":"손해보험계약의 보험자는 보험사고로 인하여 생길 피보험자의 재산상의 손해를 보상할 책임이 있다. 보상 대상은 피보험자의 손해이지 보험수익자의 손해가 아니다.","src":"상법 제665조 | 기출 2023-17"},{"t":"피보험자는 불확정한 사고가 발생하면 보험자에게 보험금 지급을 청구할 수 있다.","src":"상법 제638조 | 기출 2022-1"}]},{"머리":"피보험이익","줄":[{"t":"보험계약은 금전으로 산정할 수 있는 이익에 한하여 보험계약의 목적으로 할 수 있다. 「보험의 목적」(물건)이 아니라 「보험계약의 목적」(피보험이익)이다.","src":"상법 제668조 | 기출 2021-13 | 기출 2022-15 | 기출 2023-17 | 기출 2024-18 | 기출 2025-24 | 기출 2026-15"},{"t":"피보험이익: 보험사고가 발생하지 않았다면 피보험자가 누렸을 경제적 이해관계(금전으로 산정 가능한 것).","src":"보충"},{"t":"동일한 건물에 대하여 소유자와 담보권자(저당권자)는 서로 다른 피보험이익을 가지므로 각자 독립한 화재보험계약을 체결할 수 있다.","src":"기출 2023-24 | 기출 2024-24"},{"t":"손해: 피보험이익의 전부 또는 일부가 멸실되거나 감손된 것.","src":"기출 2022-20"},{"t":"보험금 지급의무는 보험기간 내 보험사고가 발생하고 그로 인해 피보험자의 피보험이익에 손해가 생기면 성립한다.","src":"기출 2022-20"},{"t":"보험사고 발생의 입증책임은 보험금 지급을 청구하는 보험계약자 등에게 있다.","src":"기출 2022-20"}]},{"머리":"보상 범위와 산정","줄":[{"t":"사고로 상실된 피보험자가 얻을 이익이나 보수는 당사자 간에 다른 약정이 없으면 보상할 손해액에 산입하지 아니한다. 약정이 있으면 산입할 수 있다.","src":"상법 제667조 | 기출 2021-13 | 기출 2021-20 | 기출 2022-15 | 기출 2023-17"},{"t":"보험자가 손해를 보상할 때 보험료 지급 잔액이 있으면 지급기일 미도래라도 보상할 금액에서 공제할 수 있다.","src":"상법 제677조 | 기출 2021-21 | 기출 2022-21 | 기출 2023-21 | 기출 2024-20"},{"t":"보험자는 보험사고로 인하여 부담할 책임에 대하여 다른 보험자와 재보험계약을 체결할 수 있다.","src":"상법 제661조 | 기출 2023-21 | 기출 2025-24"},{"t":"무효와 실권의 사유는 손해보험증권의 기재사항이다.","src":"상법 제666조6호 | 기출 2021-13"},{"t":"당사자 간에 보험가액을 정하지 아니한 때에는 사고발생시의 가액이 보험가액이다.","src":"상법 제671조 | 기출 2021-13"},{"t":"화재보험의 보험자는 소방 또는 손해 감소에 필요한 조치로 인하여 생긴 손해를 보상할 책임이 있다.","src":"상법 제684조 | 기출 2022-15"},{"t":"대리인에 의하여 손해보험계약을 체결한 경우 대리인이 안 사유는 본인이 안 것과 같다.","src":"상법 제646조 | 기출 2023-17"},{"t":"보험목적 양도 시 양수인은 보험계약상 권리와 의무를 승계한 것으로 추정한다.","src":"상법 제679조① | 기출 2024-18"},{"t":"사고 발생 후 목적이 보험자 부담 외 사고로 멸실되어도 이미 생긴 손해에 대한 보상 책임을 면하지 못한다.","src":"상법 제675조 | 기출 2021-21 | 기출 2024-18"},{"t":"성질·하자·자연소모로 인한 손해는 보상 책임이 없다.","src":"상법 제678조 | 기출 2021-21 | 기출 2024-18"}]},{"머리":"책임보험(참고)","줄":[{"t":"책임보험자는 피보험자가 보험기간 중의 사고로 제3자에게 배상할 책임을 진 경우 이를 보상할 책임이 있다.","src":"상법 제719조"},{"t":"피보험자가 제3자의 청구를 방어하기 위하여 지출한 재판상 또는 재판외의 필요비용은 보험의 목적에 포함된 것으로 하고, 피보험자는 보험자에게 그 비용의 선급을 청구할 수 있다.","src":"상법 제720조①"},{"t":"피보험자가 담보 제공 또는 공탁으로 재판 집행을 면할 수 있는 경우, 보험금액의 한도 내에서 보험자에게 그 담보 제공 또는 공탁을 청구할 수 있다.","src":"상법 제720조②"},{"t":"위 행위가 보험자의 지시에 의한 것이면 손해액에 그 금액을 가산한 금액이 보험금액을 초과해도 보험자가 부담한다.","src":"상법 제720조③"}]}],"함정":[{"x":"보험사고로 인하여 상실된 피보험자가 얻을 보수는 보험자가 보상할 손해액에 산입 하여야 한다.","o":"사고로 상실된 피보험자가 얻을 보수는 다른 약정이 없으면 손해액에 산입하지 아니한다.","src":"상법 제667조 | 기출 2021-13"},{"x":"보험계약자가 손해의 방지와 경감을 위하여 필요 또는 유익하였던 비용과 보상액이 보험금액을 초과한 경우에는 보험자는 보험금액의 한도내에서 이를 부담한다.","o":"손해방지 비용과 보상액이 보험금액을 초과한 경우에도 보험자가 이를 부담한다.","src":"상법 제680조① | 기출 2021-21"},{"x":"피보험자는 보험계약에서 정한 불확정한 사고가 발생한 경우 보험금의 지급을 보험자 에게 청구할 수 없다.","o":"피보험자는 불확정한 사고가 발생하면 보험자에게 보험금 지급을 청구할 수 있다.","src":"상법 제638조 | 기출 2022-1"},{"x":"보험자는 보험사고가 발생한 경우 보험금이 아닌 형태의 보험급여를 지급할 것을 약정할 수 없다.","o":"보험자는 보험금 이외의 급여(현물 등)를 지급하기로 약정할 수 있다.","src":"상법 제638조 | 기출 2022-1"},{"x":"보험기간의 시기(始期)는 보험계약 체결시점과 같아야 한다.","o":"보험기간의 시기는 계약 체결 이전으로도 정할 수 있다.","src":"상법 제643조 | 기출 2022-1"},{"x":"당사자간에 보험가액을 정한 때에는 그 가액은 사고발생시의 가액으로 정한 것으로 본다.","o":"당사자 간에 보험가액을 정한 때에는 사고발생시의 가액으로 정한 것으로 추정한다.","src":"상법 제670조 | 기출 2022-15"},{"x":"보험자는 보험사고로 인하여 생길 보험수익자의 재산상의 손해를 보상할 책임이 있다.","o":"손해보험자는 보험사고로 생길 피보험자의 재산상 손해를 보상할 책임이 있다(보험수익자 아님).","src":"상법 제665조 | 기출 2023-17"},{"x":"보험사고로 인하여 상실된 피보험자가 얻을 이익이나 보수는 보험자가 보상할 손해액에 산입한다.","o":"사고로 상실된 피보험자가 얻을 이익이나 보수는 다른 약정이 없으면 손해액에 산입하지 아니한다.","src":"상법 제667조 | 기출 2023-17"},{"x":"대리인에 의하여 손해보험계약을 체결한 경우에 대리인이 안 사유는 그 본인이 안 것과 동일한 것으로 할 수 없다.","o":"대리인에 의하여 보험계약을 체결한 경우 대리인이 안 사유는 본인이 안 것과 동일한 것으로 한다.","src":"상법 제646조 | 기출 2023-17"},{"x":"피보험자가 보험의 목적을 양도한 때에는 양수인은 보험계약상의 권리와 의무를 승계한 것으로 본다.","o":"보험목적 양도 시 양수인은 보험계약상 권리와 의무를 승계한 것으로 추정한다(간주 아님).","src":"상법 제679조① | 기출 2024-18"},{"x":"금전으로 산정할 수 있는 이익에 한하여 보험의 목적으로 할 수 있다.","o":"금전으로 산정할 수 있는 이익에 한하여 「보험계약의 목적」으로 할 수 있다(보험의 목적인 물건이 아니라 피보험이익을 가리킴).","src":"상법 제668조 | 기출 2024-18"},{"x":"보험의 목적의 성질, 하자 또는 자연소모로 인한 손해는 보험자가 이를 보상할 책임 이 있다.","o":"보험의 목적의 성질, 하자, 자연소모로 인한 손해는 보험자가 보상할 책임이 없다.","src":"상법 제678조 | 기출 2024-18"},{"x":"보험계약은 금전으로 산정할 수 없는 이익에 대해서도 보험계약의 목적으로 할 수 있다.","o":"금전으로 산정할 수 없는 이익은 보험계약의 목적으로 할 수 없다.","src":"상법 제668조 | 기출 2025-24"},{"x":"화재보험에서 동산을 보험의 목적으로 한 때에는 보험증권에 그 위치한 장소를 기재 하면 되고 그 상태나 용도까지 기재할 필요는 없다.","o":"동산이 보험의 목적이면 증권에 그 존치한 장소의 상태와 용도를 기재하여야 한다.","src":"상법 제685조2호 | 기출 2025-24"},{"x":"보험자가 보상할 손해액의 산정에 관한 비용은 보험계약자의 부담으로 한다.","o":"손해액 산정에 관한 비용은 보험자의 부담이다.","src":"상법 제676조② | 기출 2025-24"}]},"보험가액과 보험금액(초과보험ㆍ중복보험ㆍ일부보험)":{"묶음":[{"머리":"보험가액과 보험금액","줄":[{"t":"보험가액: 피보험이익을 금전적으로 산정 또는 평가한 액수. 보험금액: 계약상 보험자의 최고 보상 한도.","src":"기출 2023-12"},{"t":"보험가액과 보험금액은 일치하지 않을 수 있다.","src":"기출 2024-15"},{"t":"전부보험: 보험금액 = 보험가액. 초과보험: 보험금액 > 보험가액. 일부보험: 보험금액 < 보험가액.","src":"상법 제669조 | 상법 제674조"}]},{"머리":"기평가보험·미평가보험","줄":[{"t":"기평가보험: 당사자 간에 보험가액을 정한 때에는 그 가액은 사고발생시의 가액으로 정한 것으로 추정한다(간주 아님).","src":"상법 제670조 | 기출 2024-15 | 기출 2025-16 | 기출 2026-15"},{"t":"그 가액이 사고발생시의 가액을 현저하게 초과할 때에는 사고발생시의 가액을 보험가액으로 한다(무효가 아님).","src":"상법 제670조 단서 | 기출 2023-12 | 기출 2024-15 | 기출 2026-15"},{"t":"미평가보험: 당사자 간에 보험가액을 정하지 아니한 때에는 사고발생시의 가액을 보험가액으로 한다(계약체결시 가액 아님, 무효 아님).","src":"상법 제671조 | 기출 2021-13 | 기출 2023-12 | 기출 2024-15 | 기출 2025-16 | 기출 2026-15"}]},{"머리":"초과보험(제669조)","줄":[{"t":"보험금액이 보험계약의 목적의 가액을 현저하게 초과한 때 보험자 또는 보험계약자는 보험료와 보험금액의 감액을 청구할 수 있다.","src":"상법 제669조① | 기출 2023-11 | 기출 2025-15 | 기출 2026-14"},{"t":"보험료의 감액은 장래에 대하여서만 효력이 있다.","src":"상법 제669조① 단서 | 기출 2022-16 | 기출 2023-11"},{"t":"초과 여부를 가리는 가액은 계약당시의 가액에 의한다.","src":"상법 제669조② | 기출 2022-16 | 기출 2026-14"},{"t":"보험가액이 보험기간 중에 현저하게 감소된 때에도 감액 청구를 할 수 있다.","src":"상법 제669조③ | 기출 2022-16 | 기출 2023-11 | 기출 2024-16 | 기출 2025-15 | 기출 2026-14"},{"t":"초과보험 계약이 보험계약자의 사기로 체결된 때에는 그 계약은 무효이다. 다만 보험자는 그 사실을 안 때까지의 보험료를 청구할 수 있다.","src":"상법 제669조④ | 기출 2022-16 | 기출 2024-16 | 기출 2025-15 | 기출 2026-14"},{"t":"사기가 아닌 때에는 보험자는 보험료와 보험금액의 감액을 청구할 수 있다. 계약을 취소·해지할 수 있다는 규정은 없다.","src":"상법 제669조 | 기출 2023-11 | 기출 2024-16"}]},{"머리":"중복보험(제672조·제673조)","줄":[{"t":"정의: 동일한 보험계약의 목적과 동일한 사고에 관하여 수개의 보험계약이 동시에 또는 순차로 체결된 경우에 그 보험금액의 총액이 보험가액을 초과한 때.","src":"상법 제672조① | 기출 2022-18 | 기출 2023-18"},{"t":"효과: 보험자는 각자의 보험금액의 한도에서 연대책임을 지며, 각 보험자의 보상책임은 각자의 보험금액의 비율에 따른다.","src":"상법 제672조① | 기출 2021-17 | 기출 2022-19 | 기출 2023-18"},{"t":"통지: 수개의 보험계약을 체결하는 경우 보험계약자는 각 보험자에 대하여 각 보험계약의 내용을 통지하여야 한다. 통지 위반에 대한 취소권 규정은 없다.","src":"상법 제672조② | 기출 2021-17 | 기출 2022-18 | 기출 2024-17"},{"t":"사기로 체결된 중복보험은 무효이고 보험자는 그 사실을 안 때까지의 보험료를 청구할 수 있다(제669조제4항 준용).","src":"상법 제672조③ | 기출 2023-18 | 기출 2024-17 | 기출 2026-17"},{"t":"보험자 1인에 대한 권리의 포기는 다른 보험자의 권리의무에 영향을 미치지 아니한다.","src":"상법 제673조 | 기출 2021-17 | 기출 2022-19 | 기출 2023-18 | 기출 2024-17"},{"t":"공동보험(하나의 보험계약을 수인의 보험자와 체결)과 구별된다.","src":"기출 2022-18"},{"t":"계산 순서: 손해액 → 각 보험자 분담액 = 손해액 × (그 보험금액 ÷ 보험금액 총액). 예: A 10억·B 10억, 손해 10억이면 각 5억. A가 10억을 전액 지급하면 B에게 5억 구상.","src":"상법 제672조① | 기출 2026-17"},{"t":"각 보험자의 책임 한도는 자기 보험금액. 사례 2022-19: 가액 3억 아파트에 A·B 각 3억 보험 → 전손 시 각 3억씩 받는 것은 불가, A·B는 각자 3억 한도에서 연대책임.","src":"상법 제672조① | 기출 2022-19"}]},{"머리":"일부보험(제674조)","줄":[{"t":"보험가액의 일부를 보험에 붙인 경우 보험자는 보험금액의 보험가액에 대한 비율에 따라 보상할 책임을 진다.","src":"상법 제674조 | 기출 2021-18 | 기출 2023-19"},{"t":"다만 당사자 간에 다른 약정이 있는 때에는 보험자는 보험금액의 한도 내에서 그 손해를 보상할 책임을 진다(실손보상 약정).","src":"상법 제674조 단서 | 기출 2023-19 | 기출 2025-18 | 기출 2026-18"},{"t":"공식: 보상액 = 손해액 × (보험금액 ÷ 보험가액). 단 보험금액 한도. 예: 가액 2억·금액 1억, 전손 → 1억, 손해 8천만원 → 4천만원, 손해 1억원 → 5천만원.","src":"상법 제674조 | 기출 2021-18"},{"t":"일부보험에서 일부손해 시 비례보상하므로 손해액이 보상액보다 크다.","src":"기출 2021-19"},{"t":"일부보험도 의도적으로 가능하다. 비례보상 규정은 약정으로 배제되므로 강행규정이 아니다.","src":"상법 제674조 | 기출 2021-19"},{"t":"일부보험에서도 잔존물대위는 인정된다(보험금액의 보험가액에 대한 비율).","src":"상법 제681조 | 기출 2021-19 | 기출 2024-22 | 기출 2025-21"},{"t":"전부보험 체결 후 물가 상승 등으로 보험가액이 현저히 오르면 일부보험이 될 수 있다.","src":"보충 | 기출 2023-19"}]}],"함정":[{"x":"계약체결의 시점에 의도적으로 보험가액보다 낮게 보험금액을 약정하는 것은 허용되지 않는다.","o":"일부보험은 인정되며, 보험가액보다 낮은 보험금액을 약정하는 것도 허용된다.","src":"상법 제674조 | 기출 2021-19"},{"x":"일부보험에 관한 상법의 규정은 강행규정이다.","o":"일부보험의 비례보상 원칙은 당사자 간 다른 약정이 있으면 배제되므로(제674조 단서) 강행규정이 아니다.","src":"상법 제674조 | 기출 2021-19"},{"x":"일부보험의 경우에는 잔존물 대위가 인정되지 않는다.","o":"일부보험에도 잔존물대위가 인정되며, 보험자가 취득할 권리는 보험금액의 보험가액에 대한 비율에 따른다.","src":"상법 제681조 | 기출 2021-19"},{"x":"초과보험에 있어서 보험계약의 목적의 가액은 사고 발생시의 가액에 의하여 정한다.","o":"초과보험 여부를 가리는 가액은 계약당시의 가액에 의하여 정한다.","src":"상법 제669조② | 기출 2022-16"},{"x":"보험금액이 보험계약의 목적의 가액을 현저하게 초과한 때에는 보험계약자는 소급하 여 보험료의 감액을 청구할 수 있다.","o":"보험료의 감액은 장래에 대하여서만 효력이 있다(소급 아님).","src":"상법 제669조① | 기출 2022-16"},{"x":"보험가액이 보험계약 당시가 아닌 보험기간 중에 현저하게 감소된 때에는 보험자는 보험료와 보험금액의 감액을 청구할 수 없다.","o":"보험가액이 보험기간 중 현저하게 감소된 때에도 감액 청구를 할 수 있다.","src":"상법 제669조③ | 기출 2022-16"},{"x":"보험계약자가 중복보험의 체결사실을 보험자에게 통지하지 아니한 경우 보험자는 보험계약을 취소할 수 있다.","o":"중복보험 통지의무 위반에 대한 취소권은 상법에 없고, 사기로 체결된 경우에는 무효이다.","src":"상법 제672조③ | 기출 2022-18"},{"x":"보험계약자가 청구한 보험료의 감액은 계약체결일부터 소급하여 그 효력이 있다.","o":"초과보험에서 보험료의 감액은 장래에 대하여서만 효력이 있다.","src":"상법 제669조① | 기출 2023-11"},{"x":"보험가액이 보험기간 중에 현저하게 감소된 때에도 보험계약자는 보험료의 감액을 청구할 수 없다.","o":"보험가액이 보험기간 중 현저하게 감소된 때에도 보험자 또는 보험계약자는 감액을 청구할 수 있다.","src":"상법 제669조③ | 기출 2023-11"},{"x":"보험계약자의 사기로 인하여 체결된 초과보험의 경우 보험자는 그 계약을 체결한 날부터 1월내에 계약을 해지할 수 있다.","o":"사기로 체결된 초과보험은 해지가 아니라 무효이며, 보험자는 사실을 안 때까지의 보험료를 청구할 수 있다.","src":"상법 제669조④ | 기출 2023-11"},{"x":"당사자간에 보험가액을 정한 때에는 그 가액은 사고발생시의 가액으로 정한 것으로 본다.","o":"당사자 간에 보험가액을 정한 때에는 사고발생시의 가액으로 정한 것으로 추정한다(간주 아님).","src":"상법 제670조 | 기출 2023-12"},{"x":"보험계약자의 사기로 인하여 중복보험 계약이 체결된 경우 보험자는 그 사실을 안 때 까지의 보험료를 청구할 수 없다.","o":"사기로 체결된 중복보험은 무효이며, 보험자는 그 사실을 안 때까지의 보험료를 청구할 수 있다.","src":"상법 제672조③, 제669조④ | 기출 2023-18"},{"x":"일부보험이란 보험가액이 보험금액에 미달되는 경우를 말한다.","o":"일부보험이란 보험금액이 보험가액에 미달하는 경우를 말한다.","src":"상법 제674조 | 기출 2023-19"},{"x":"당사자간에 다른 약정이 없는한 보험자는 보험가액의 보험금액에 대한 비율에 따라 보상할 책임을 진다.","o":"일부보험의 비례보상은 보험금액의 보험가액에 대한 비율에 따른다(보험가액의 보험금액에 대한 비율 아님).","src":"상법 제674조 | 기출 2023-19"},{"x":"전부보험계약 체결후 물가등귀로 인하여 보험가액이 현저히 인상되더라도 일부보험은 발생하지 아니한다.","o":"전부보험 체결 후 물가 상승 등으로 보험가액이 현저히 인상되면 일부보험이 될 수 있다.","src":"보충 | 기출 2023-19 | 기출 2023-19"},{"x":"보험계약의 당사자간에 보험가액을 정한 경우 그 가액이 사고발생시의 가액을 현저하게 초과할 경우 보험계약은 무효이다.","o":"가액이 사고발생시의 가액을 현저히 초과해도 계약은 무효가 아니고, 사고발생시의 가액을 보험가액으로 한다.","src":"상법 제670조 | 기출 2024-15"},{"x":"보험기간 중 화재가 발생하여 甲의 재산이 전소되어 10억원의 손해를 입은 경우 甲은 A, B보험회사에게 각각 5억원까지 보험금청구권을 행사할 수 있다.","o":"중복보험의 보험금액 총액이 보험가액을 초과하면 보험자들은 각자의 보험금액 한도에서 연대책임을 지고 각자 보험금액 비율로 보상한다(출제 오답, 사례 수치 미확인).","src":"상법 제672조① | 기출 2024-17"},{"x":"보험가액이 보험금액을 현저하게 초과한 때에는 보험자 또는 보험계약자는 보험료와 보험금액의 감액을 청구할 수 있다.","o":"감액 청구는 보험「금액」이 보험「가액」을 현저하게 초과한 때(초과보험)에 한다.","src":"상법 제669조① | 기출 2025-15"},{"x":"당사자간에 보험가액을 정한 때에는 그 가액은 사고발생시의 가액으로 정한 것으로 간주한다.","o":"당사자 간에 보험가액을 정한 때 그 가액은 사고발생시의 가액으로 「추정」한다(간주 아님).","src":"상법 제670조 | 기출 2025-16"},{"x":"협정보험가액이 사고발생시의 가액을 현저하게 초과할 때에는 협정보험가액을 보험가액 으로 한다.","o":"협정보험가액이 사고발생시의 가액을 현저히 초과하면 사고발생시의 가액을 보험가액으로 한다.","src":"상법 제670조 | 기출 2025-16"},{"x":"보험가액을 정하지 않은 경우 그 보험계약은 무효로 한다.","o":"보험가액을 정하지 않은 경우(미평가보험)에도 계약은 유효하고 사고발생시의 가액을 보험가액으로 한다.","src":"상법 제671조 | 기출 2025-16"},{"x":"B보험자가 보험금을 지급하지 않은 경우 A보험자는 甲에게 보험금으로 12억원을 지급하여야 한다.","o":"중복보험에서 한 보험자가 지급하지 않아도 다른 보험자는 자기 보험금액 한도에서 연대책임을 지며, 초과 지급분은 비율에 따라 구상한다(출제 오답, 사례 수치 미확인).","src":"상법 제672조① | 기출 2025-17"},{"x":"일부보험의 보험가액 산정기준은 언제나 계약 체결시로 한다.","o":"보험가액은 원칙적으로 사고발생시의 가액이고, 계약당시 가액은 초과보험 판단에 쓴다(출제 오답, 일부보험 산정시점 별도 규정 없음).","src":"상법 제669조②, 제671조 | 기출 2025-18"},{"x":"보험기간 중에 보험가액이 현저하게 감소된 때에는 보험자는 보험료와 보험금액의 감액을 청구할 수 없다.","o":"보험가액이 보험기간 중 현저히 감소된 때 보험자는 보험료와 보험금액의 감액을 청구할 수 있다.","src":"상법 제669조③ | 기출 2026-14"},{"x":"보험계약 당사자간에 보험가액을 정하지 아니한 때에는 계약체결시의 가액을 보험가액 으로 한다.","o":"보험가액을 정하지 아니한 때에는 사고발생시의 가액을 보험가액으로 한다.","src":"상법 제671조 | 기출 2026-15"}]},"보험사고의 통지와 손해액의 산정":{"묶음":[{"머리":"사고 발생의 통지(제657조)","줄":[{"t":"보험계약자 또는 피보험자나 보험수익자는 보험사고의 발생을 안 때 지체없이 보험자에게 그 통지를 발송하여야 한다.","src":"상법 제657조① | 기출 2021-12 | 기출 2022-12 | 기출 2023-4 | 기출 2023-16 | 기출 2024-10 | 기출 2025-11 | 기출 2026-10"},{"t":"통지의무자는 보험계약자, 피보험자, 보험수익자 모두이다. 통지 상대방은 보험자이다.","src":"상법 제657조① | 기출 2021-12 | 기출 2023-16"},{"t":"해태 효과: 통지의무를 해태함으로 인하여 손해가 증가된 때 보험자는 그 증가된 손해를 보상할 책임이 없다. 해지권은 규정하지 않는다.","src":"상법 제657조② | 기출 2021-12 | 기출 2023-16 | 기출 2024-10 | 기출 2025-11"}]},{"머리":"보험금 지급(제658조)","줄":[{"t":"약정기간이 있는 경우: 그 기간 내에 지급할 보험금액을 정하여 지급한다.","src":"상법 제658조 | 기출 2021-14 | 기출 2023-13"},{"t":"약정기간이 없는 경우: 제657조제1항의 통지를 받은 후 지체없이 지급할 보험금액을 정하고, 정하여진 날부터 10일 내에 피보험자 또는 보험수익자에게 지급한다.","src":"상법 제658조 | 기출 2021-14 | 기출 2022-12 | 기출 2023-13 | 기출 2024-11 | 기출 2025-12 | 기출 2026-10"},{"t":"보험계약자의 동의 없이 보험자와 피보험자 사이에 한 보험금 지급기한 유예 합의는 유효하다.","src":"기출 2021-14"},{"t":"손해보상은 원칙적으로 금전으로 하되, 당사자의 합의로 전부 또는 일부를 현물로 보상할 수 있다.","src":"기출 2021-20"}]},{"머리":"보험자의 책임 개시·면책(관련)","줄":[{"t":"책임 개시: 다른 약정이 없으면 최초의 보험료를 지급받은 때(청약한 때·계약 성립한 때 아님).","src":"상법 제656조 | 기출 2022-12 | 기출 2024-10"},{"t":"보험계약자 또는 피보험자나 보험수익자의 고의 또는 중대한 과실로 사고가 생긴 때 보험자는 보험금액을 지급할 책임이 없다.","src":"상법 제659조① | 기출 2022-12 | 기출 2023-13 | 기출 2024-11 | 기출 2026-10"},{"t":"전쟁 기타의 변란으로 사고가 생긴 때에는 다른 약정이 없으면 보험자는 지급 책임이 없다.","src":"상법 제660조 | 기출 2023-13 | 기출 2026-10"},{"t":"보험자가 파산선고를 받고 보험계약자가 해지하지 않은 채 3월이 경과하면 계약은 효력을 잃는다.","src":"상법 제654조② | 기출 2024-11"},{"t":"보험금 청구권은 3년의 시효로 소멸한다.","src":"상법 제662조"}]},{"머리":"손해액의 산정(제676조)","줄":[{"t":"보험자가 보상할 손해액은 그 손해가 발생한 때와 곳의 가액에 의하여 산정한다.","src":"상법 제676조① | 기출 2022-21 | 기출 2023-20 | 기출 2024-19 | 기출 2026-19"},{"t":"당사자 간에 다른 약정이 있는 때에는 신품가액에 의하여 손해액을 산정할 수 있다.","src":"상법 제676조① 단서 | 기출 2021-20 | 기출 2022-21 | 기출 2023-20 | 기출 2024-19 | 기출 2026-19"},{"t":"손해액의 산정에 관한 비용은 보험자의 부담이다.","src":"상법 제676조② | 기출 2021-20 | 기출 2022-21 | 기출 2023-20 | 기출 2024-19 | 기출 2025-24 | 기출 2026-19"},{"t":"상실된 피보험자가 얻을 이익이나 보수는 다른 약정이 없으면 손해액에 산입하지 아니한다.","src":"상법 제667조 | 기출 2021-20 | 기출 2024-19"}]},{"머리":"보험료 잔액의 공제(제677조)","줄":[{"t":"보험자가 손해를 보상할 때 보험료의 지급을 받지 아니한 잔액이 있으면, 그 지급기일이 도래하지 아니한 때라도 보상할 금액에서 이를 공제할 수 있다.","src":"상법 제677조 | 기출 2021-21 | 기출 2022-21 | 기출 2023-21 | 기출 2024-20"},{"t":"공제는 「할 수 있다」(의무 아님). 잔액이 있다는 이유로 즉시 해지하거나 보상 전부를 거절할 수 있다는 규정은 없다.","src":"상법 제677조 | 기출 2024-20"},{"t":"보험자가 부담할 손해가 생긴 후 그 목적이 보험자 부담 외 사고로 멸실된 때에도 이미 생긴 손해를 보상할 책임을 면하지 못한다.","src":"상법 제675조 | 기출 2021-21 | 기출 2026-18"},{"t":"보험의 목적의 자연소모로 인한 손해는 보험자가 보상할 책임이 없다.","src":"상법 제678조 | 기출 2021-21 | 기출 2026-18"},{"t":"손해방지 필요·유익 비용과 보상액이 보험금액을 초과해도 보험자가 부담한다.","src":"상법 제680조① | 기출 2021-21"},{"t":"일부보험에서 약정으로 보험금액의 한도 내에서 손해 전부를 보상하게 할 수 있다.","src":"상법 제674조 단서 | 기출 2026-18"}]}],"함정":[{"x":"상법은 보험사고발생의 통지의무위반 시 보험자의 계약해지권을 규정하고 있다.","o":"상법은 사고 발생 통지의무 위반에 대해 해지권을 규정하지 않고, 증가된 손해에 대한 보상 책임 면제만 규정한다.","src":"상법 제657조② | 기출 2021-12"},{"x":"보험계약자는 보험사고의 발생을 안 때에는 상당한 기간 내에 보험자에게 그 통지를 발송하여야 한다.","o":"보험계약자 등은 사고 발생을 안 때 지체없이 보험자에게 통지를 발송하여야 한다.","src":"상법 제657조① | 기출 2021-12"},{"x":"보험수익자는 보험사고발생의 통지의무자에 포함되지 않는다.","o":"보험수익자도 사고 발생 통지의무자이다.","src":"상법 제657조① | 기출 2021-12"},{"x":"보험금액의 지급에 관하여 약정기간이 없는 경우, 보험금액이 정하여진 날부터 1월내에 보험수익자에게 보험금액을 지급하여야 한다.","o":"약정기간이 없으면 보험금액이 정하여진 날부터 10일 내에 지급하여야 한다.","src":"상법 제658조 | 기출 2021-14"},{"x":"손해액 산정에 필요한 비용은 보험자와 보험계약자 및 보험수익자가 공동으로 부담한다.","o":"손해액 산정에 관한 비용은 보험자가 부담한다.","src":"상법 제676조② | 기출 2021-20"},{"x":"보험수익자가 보험사고의 발생을 안 때에는 보험자에게 그 통지를 할 의무가 없다.","o":"보험수익자도 사고 발생을 안 때 보험자에게 지체없이 통지를 발송할 의무가 있다.","src":"상법 제657조① | 기출 2022-12"},{"x":"보험자는 보험금액의 지급에 관하여 약정기간이 없는 경우 지급할 보험금액이 정하여진 날로부터 5일내에 지급하여야 한다.","o":"약정기간이 없으면 정하여진 날부터 10일 내에 지급하여야 한다(5일 아님).","src":"상법 제658조 | 기출 2022-12"},{"x":"보험자의 책임은 당사자간에 다른 약정이 없으면 보험계약자가 보험계약의 체결을 청약한 때로부터 개시한다.","o":"보험자의 책임은 다른 약정이 없으면 최초 보험료의 지급을 받은 때로부터 개시한다.","src":"상법 제656조 | 기출 2022-12"},{"x":"손해액의 산정에 관한 비용은 보험계약자의 부담으로 한다.","o":"손해액 산정에 관한 비용은 보험자의 부담이다.","src":"상법 제676조② | 기출 2022-21"},{"x":"보험사고가 전쟁으로 인하여 생긴 때에도 당사자간에 다른 약정이 없으면 보험자는 보험금액을 지급할 책임이 있다.","o":"전쟁 기타의 변란으로 사고가 생긴 때에는 다른 약정이 없으면 보험자는 보험금액 지급 책임이 없다.","src":"상법 제660조 | 기출 2023-13"},{"x":"당사자간에 다른 약정이 없는 경우 보험자가 보상할 손해액은 그 손해가 발생한 때의 보험계약 체결지의 가액에 의하여 산정한다.","o":"손해액은 그 손해가 발생한 때와 곳의 가액에 의하여 산정한다(체결지 아님).","src":"상법 제676조① | 기출 2023-20"},{"x":"보험계약자가 보험사고의 발생을 알았음에도 지체없이 보험자에게 그 통지를 발송하지 않은 경우 보험자는 계약을 해지할 수 있다.","o":"상법은 사고 발생 통지 해태에 대해 해지권을 두지 않고, 증가된 손해에 대한 보상 책임만 면제한다.","src":"상법 제657조② | 기출 2024-10"},{"x":"보험자가 파산선고를 받았으나 보험계약자가 계약을 해지하지 않은 채 3월이 경과한 후에 보험사고가 발생하여도 보험자는 보험금액 지급 책임이 있다.","o":"보험자 파산선고 후 계약자가 해지하지 않으면 파산선고 후 3월이 경과한 때 효력을 잃으므로, 그 후 사고에는 지급 책임이 없다.","src":"상법 제654조② | 기출 2024-11"},{"x":"보험자가 보상할 손해액은 보험계약을 체결한 때와 곳의 가액에 의하여 산정한다.","o":"보험자가 보상할 손해액은 그 손해가 발생한 때와 곳의 가액에 의하여 산정한다.","src":"상법 제676조① | 기출 2024-19"},{"x":"보험사고로 인하여 상실된 피보험자가 얻을 이익이나 보수는 보험자가 보상할 손해액에 산입하여야 한다.","o":"사고로 상실된 피보험자가 얻을 이익이나 보수는 다른 약정이 없으면 손해액에 산입하지 아니한다.","src":"상법 제667조 | 기출 2024-19"},{"x":"손해액의 산정에 관한 비용은 보험계약자의 부담으로 한다.","o":"손해액 산정에 관한 비용은 보험자의 부담이다.","src":"상법 제676조② | 기출 2024-19"},{"x":"보험자는 보험료의 지급을 받지 아니한 잔액이 있으면 보험계약을 즉시 해지할 수 있다.","o":"상법은 보험료 잔액이 있다는 이유로 즉시 해지할 수 있다고 규정하지 않고, 보상금에서 공제할 수 있다고만 규정한다.","src":"상법 제677조 | 기출 2024-20"},{"x":"보험자는 지급기일이 도래하였으나 지급받지 않은 보험료 잔액을 보상할 금액에서 공제하여야 한다.","o":"보험료 잔액은 보상액에서 공제「할 수 있다」(공제 의무 아님).","src":"상법 제677조 | 기출 2024-20"},{"x":"보험자는 지급기일이 도래한 보험료 잔액의 지급이 있을 때까지 그 손해보상을 전부 거절할 수 있다.","o":"보험자는 보험료 잔액만 보상액에서 공제할 수 있고, 손해보상 전부를 거절할 수 있다는 규정은 없다.","src":"상법 제677조 | 기출 2024-20"},{"x":"보험계약자가 통지의무를 위반할 경우 보험자는 보험금 전액의 지급책임을 면한다.","o":"통지의무 해태로 손해가 증가된 경우 보험자는 증가된 손해에 대해서만 책임을 면한다.","src":"상법 제657조② | 기출 2025-11"},{"x":"보험계약자는 보험사고의 발생을 안 때라도 보험자에게 그 통지를 발송할 의무가 없다.","o":"보험계약자도 사고 발생을 안 때에는 지체없이 보험자에게 통지를 발송할 의무가 있다.","src":"상법 제657조① | 기출 2026-10"},{"x":"보험사고가 피보험자의 경과실로 인하여 생긴 때에는 보험자는 보험금액을 지급할 책임이 없다.","o":"면책은 고의 또는 중대한 과실로 사고가 생긴 때이고, 피보험자의 경과실은 면책사유가 아니다.","src":"상법 제659조① | 기출 2026-18"},{"x":"보험의 목적에 관하여 보험자가 부담할 손해가 생긴 이후 그 목적이 보험자가 부담하 지 아니하는 보험사고의 발생으로 인하여 멸실된 때에는 보험자는 이미 생긴 손해를 보상할 책임을 면한다.","o":"보험자가 부담할 손해가 생긴 후 목적이 보험자 부담 외 사고로 멸실되어도 이미 생긴 손해를 보상할 책임을 면하지 못한다.","src":"상법 제675조 | 기출 2026-18"},{"x":"보험의 목적의 자연소모로 인한 손해는 보험자가 이를 보상할 책임이 있다.","o":"자연소모로 인한 손해는 보험자가 보상할 책임이 없다.","src":"상법 제678조 | 기출 2026-18"}]},"손해방지의무":{"묶음":[{"머리":"의무의 내용(제680조)","줄":[{"t":"보험계약자와 피보험자는 손해의 방지와 경감을 위하여 노력하여야 한다. 의무 주체는 보험계약자와 피보험자 둘 다이다.","src":"상법 제680조① | 기출 2022-23 | 기출 2023-22 | 기출 2024-21 | 기출 2025-20 | 기출 2026-21"},{"t":"의무는 보험사고 발생 이후(사고 발생을 알았을 때)의 손해 방지·경감을 위한 것이다. 사고 이전에만 부담하는 의무가 아니다.","src":"기출 2024-21"},{"t":"노력한 이상 실제로 손해가 방지·경감되었는지는 묻지 않는다.","src":"기출 2026-21 | 기출 2024-21"}]},{"머리":"비용의 부담","줄":[{"t":"손해의 방지·경감을 위하여 필요 또는 유익하였던 비용은 보험자가 부담한다.","src":"상법 제680조① | 기출 2022-23 | 기출 2023-22"},{"t":"필요·유익 비용과 보상액이 보험금액을 초과한 경우라도 보험자가 이를 부담한다(보험금액 한도 아님).","src":"상법 제680조① 단서 | 기출 2021-21 | 기출 2022-23 | 기출 2024-21 | 기출 2025-20 | 기출 2026-21"},{"t":"비용 부담 요건은 비용이 필요 또는 유익했는지이고, 손해 방지에 유효하게 영향을 주었을 것은 요건이 아니다.","src":"상법 제680조① | 기출 2024-21"},{"t":"사례(2023-22): 보험금액 1억원, 보상액 8천만원, 방지·경감 비용 합계 4천만원(1천+3천) → 8천+4천 = 1억 2천만원을 보험자가 부담한다. 「1억원 한도」는 틀림. 계약자·피보험자(소유자) 모두 방지 노력 의무가 있고, 각자 지출한 필요·유익 비용은 모두 보험자 부담.","src":"상법 제680조① | 기출 2023-22"}]},{"머리":"의무 위반","줄":[{"t":"피보험자가 고의 또는 중과실로 손해방지의무를 위반한 경우, 보험자는 의무 위반과 상당인과관계가 있는 손해에 대하여 배상을 청구할 수 있다.","src":"기출 2022-23"},{"t":"상법에는 손해방지의무 위반을 이유로 한 보험자의 해지권 규정이 없다.","src":"상법 제680조 | 기출 2026-21"}]}],"함정":[{"x":"손해방지를 위하여 필요 또는 유익하였던 비용과 보상액이 보험금액을 초과한 경우에는 보험금액의 한도에서만 보험자가 이를 부담한다.","o":"필요·유익 비용과 보상액이 보험금액을 초과한 경우에도 보험자가 이를 부담한다.","src":"상법 제680조① | 기출 2022-23"},{"x":"손해방지의무는 보험계약자는 부담하지 않고 피보험자만 부담하는 의무이다.","o":"손해방지의무는 보험계약자와 피보험자 모두 부담한다.","src":"상법 제680조① | 기출 2024-21"},{"x":"손해방지의무는 보험사고가 발생하기 이전에 부담하는 의무이다.","o":"손해방지의무는 보험사고 발생 이후에 손해의 방지·경감을 위하여 부담하는 의무이다.","src":"보충 | 기출 2024-21 | 기출 2024-21"},{"x":"손해방지의무의 이행을 위하여 필요 또는 유익하였던 비용은 실제로 손해의 방지와 경감에 유효하게 영향을 준 경우에만 보험자가 이를 부담한다.","o":"필요 또는 유익하였던 비용이면 실제로 손해 방지·경감의 효과가 있었는지와 관계없이 보험자가 부담한다.","src":"상법 제680조①, 기출 2026-21 | 기출 2024-21"},{"x":"보험계약자가 손해방지의무의 이행에 필요했던 비용과 보상액이 보험금액을 초과한 경우 그 초과부분은 보험계약자가 부담한다.","o":"필요·유익 비용과 보상액이 보험금액을 초과해도 초과분까지 보험자가 부담한다.","src":"상법 제680조① | 기출 2025-20"},{"x":"보험계약자가 손해방지의무를 다하지 않은 경우 보험자는 계약을 해지할 수 있다.","o":"상법에는 손해방지의무 위반을 이유로 한 보험자의 해지권 규정이 없다.","src":"상법 제680조 | 기출 2026-21"}]},"보험자대위(잔존물대위ㆍ청구권대위)":{"묶음":[{"머리":"잔존물대위(제681조)","줄":[{"t":"요건: 보험의 목적의 「전부」가 멸실하고 보험자가 「보험금액의 전부」를 지급한 때. 일부 멸실·일부 지급만으로는 성립하지 않는다.","src":"상법 제681조 | 기출 2021-22 | 기출 2022-24 | 기출 2024-22 | 기출 2025-21 | 기출 2026-22"},{"t":"효과: 보험자는 그 목적에 대한 피보험자의 권리를 취득한다.","src":"상법 제681조 | 기출 2022-24 | 기출 2025-21"},{"t":"일부보험의 경우 보험자가 취득할 권리는 보험금액의 보험가액에 대한 비율에 따라 정한다.","src":"상법 제681조 단서 | 기출 2022-24 | 기출 2026-22"},{"t":"권리 이전 시점: 보험자가 보험금액의 전부를 지급한 때 물권변동 절차 없이 이전된다(청구받은 때·절차를 마친 때 아님).","src":"기출 2024-22 | 기출 2021-22 | 기출 2025-21"},{"t":"피보험자는 보험금액 전부를 지급받은 후에는 잔존물을 임의로 처분할 수 없다.","src":"기출 2024-22"}]},{"머리":"제3자에 대한 청구권대위(제682조)","줄":[{"t":"손해가 제3자의 행위로 발생한 경우, 보험금을 지급한 보험자는 그 지급한 금액의 한도에서 제3자에 대한 보험계약자 또는 피보험자의 권리를 취득한다(지급 전이 아님, 추정 아님).","src":"상법 제682조① | 기출 2021-22 | 기출 2023-23 | 기출 2025-22"},{"t":"보험자가 보상할 보험금의 일부를 지급한 경우에는 피보험자의 권리를 침해하지 아니하는 범위에서 그 권리를 행사할 수 있다.","src":"상법 제682조① 단서 | 기출 2025-22 | 기출 2026-22"},{"t":"권리가 보험계약자·피보험자와 생계를 같이 하는 가족에 대한 것인 경우, 보험자는 그 권리를 취득하지 못한다.","src":"상법 제682조② | 기출 2022-25 | 기출 2026-22"},{"t":"다만 손해가 그 가족의 고의로 인하여 발생한 경우에는 권리를 취득한다.","src":"상법 제682조② 단서 | 기출 2023-23 | 기출 2025-22"},{"t":"사례(2023-23): 경과실로 화재를 낸 거래처 지인 → 보험자는 지급액 한도에서 취득. 생계를 달리하는 자녀(중과실) → 취득 가능. 생계를 같이 하는 배우자의 고의 방화 → 취득 가능.","src":"상법 제682조 | 기출 2023-23"},{"t":"제3자에 대한 보험대위의 취지는 이득금지 원칙의 실현과 부당한 면책의 방지에 있다.","src":"기출 2022-25 | 기출 2025-22"},{"t":"보험약관상 보험자가 면책되는 사고임에도 보험금을 지급한 경우에는 제3자에 대한 권리를 대위취득할 수 없다.","src":"기출 2022-25"},{"t":"재보험에도 제3자에 대한 보험자대위가 적용된다.","src":"기출 2021-22"}]},{"머리":"두 대위의 비교","줄":[{"t":"잔존물대위: 목적의 전부 멸실 + 보험금액 전부 지급 → 목적에 대한 피보험자의 권리 취득(물권 등).","src":"상법 제681조"},{"t":"청구권대위: 제3자 행위로 손해 → 보험금 지급 시 지급액 한도에서 제3자에 대한 권리 취득(채권).","src":"상법 제682조"}]}],"함정":[{"x":"손해가 제3자의 행위로 인하여 발생한 경우에 보험금을 지급하기 전이라도 보험자는 그 제3자에 대한 보험계약자의 권리를 취득한다.","o":"보험자는 보험금을 지급한 때에 그 지급한 금액의 한도에서 제3자에 대한 권리를 취득한다(지급 전이 아님).","src":"상법 제682조① | 기출 2021-22"},{"x":"잔존물에 대한 권리가 보험자에게 이전되는 시점은 보험자가 보험금액을 전부 지급하고, 물권변동 절차를 마무리한 때이다.","o":"보험금액의 전부를 지급한 때 잔존물에 대한 권리는 물권변동 절차 없이 보험자에게 이전된다.","src":"기출 2024-22 | 기출 2021-22"},{"x":"재보험에 대하여는 제3자에 대한 보험자대위가 적용되지 않는다.","o":"재보험에도 제3자에 대한 보험자대위가 적용된다.","src":"기출 2021-22 | 기출 2021-22"},{"x":"甲의 고의로 화재보험계약의 보험기간 중에 화재가 발생한 경우 B보험회사는 A보험 회사에게 보험금 지급의무가 있다.","o":"보험계약자 등의 고의로 사고가 생긴 때에는 보험자는 보험금액 지급 책임이 없다.","src":"상법 제659조① | 기출 2024-12"},{"x":"A보험회사의 B보험회사에 대한 보험금청구권은 1년간 행사하지 아니하면 시효의 완성으로 소멸한다.","o":"보험금청구권의 소멸시효는 3년이다.","src":"상법 제662조 | 기출 2024-12"},{"x":"B보험회사의 A보험회사에 대한 보험료청구권은 6개월간 행사하지 아니하면 시효의 완성으로 소멸한다.","o":"보험료청구권의 소멸시효는 2년이다.","src":"상법 제662조 | 기출 2024-12"},{"x":"일부보험의 경우에는 잔존물대위가 인정되지 않는다.","o":"일부보험에도 잔존물대위가 인정되며, 보험자가 취득할 권리는 보험금액의 보험가액에 대한 비율에 따른다.","src":"상법 제681조 | 기출 2024-22"},{"x":"보험자가 전체 보험금의 일부를 지급한 경우에도 그 지급에 비례하여 보험대위가 성립한다.","o":"보험대위(잔존물대위)는 목적의 전부가 멸실하고 보험금액의 전부를 지급한 때 성립하며, 일부 지급에 비례하여 성립하지 않는다.","src":"상법 제681조 | 기출 2025-21"},{"x":"잔존하는 보험목적에 관한 피보험자의 권리가 보험자에게 이전하는 시점은 보험자가 보험금을 청구받은 때이다.","o":"권리는 보험자가 보험금액 전부를 지급한 때 이전된다(청구받은 때 아님).","src":"기출 2024-22 | 기출 2025-21"},{"x":"일부보험에서는 잔존물대위가 성립할 여지가 없다.","o":"일부보험에서도 잔존물대위가 성립한다(비율에 따라 취득).","src":"상법 제681조 | 기출 2025-21"},{"x":"손해가 제3자의 행위로 인하여 발생한 경우에 보험금을 지급한 보험자는 그 지급한 금액의 한도에서 그 제3자에 대한 보험계약자 또는 피보험자의 권리를 취득하는 것으 로 추정한다.","o":"보험금을 지급한 보험자는 그 지급한 금액의 한도에서 제3자에 대한 권리를 취득한다(추정 규정이 아님).","src":"상법 제682조① | 기출 2025-22"},{"x":"보험의 목적의 일부가 멸실한 경우에 보험금액을 지급한 보험자는 그 목적에 대한 피 보험자의 권리를 취득한다.","o":"보험대위(잔존물대위)는 보험의 목적 「전부」가 멸실하고 보험금액 「전부」를 지급한 경우에 성립한다.","src":"상법 제681조 | 기출 2026-22"}]},"보험목적의 양도":{"묶음":[{"머리":"제679조","줄":[{"t":"피보험자가 보험의 목적을 양도한 때에는 양수인은 보험계약상의 권리와 의무를 승계한 것으로 추정한다. (간주가 아니다. 권리만 승계하는 것이 아니다.)","src":"상법 제679조① | 기출 2021-23 | 기출 2024-18 | 기출 2025-19 | 기출 2026-20"},{"t":"보험의 목적의 양도인 또는 양수인은 보험자에 대하여 지체없이 그 사실을 통지하여야 한다. 공동 통지가 아니라 어느 한쪽이 하면 된다.","src":"상법 제679조② | 기출 2023-21 | 기출 2025-19 | 기출 2026-20"},{"t":"통지를 하지 아니한 경우 보험자의 해지권은 상법에 없다.","src":"상법 제679조 | 기출 2026-20"},{"t":"건물을 양도한 사례(2023-21): 乙(양수인)은 권리·의무를 승계한 것으로 추정, 甲 또는 乙은 보험자에 지체없이 통지.","src":"상법 제679조 | 기출 2023-21"}]}],"함정":[{"x":"피보험자가 보험의 목적을 양도한 때에는 양수인은 보험계약상의 권리만을 승계한다.","o":"양수인은 보험계약상 권리와 의무를 모두 승계한 것으로 추정한다.","src":"상법 제679조① | 기출 2025-19"},{"x":"피보험자가 보험의 목적을 양도한 때에는 양도인과 양수인이 공동으로 보험자에게 통지하여야 한다.","o":"양도인 또는 양수인은 각자 보험자에게 지체없이 그 사실을 통지하여야 한다.","src":"상법 제679조② | 기출 2025-19"},{"x":"피보험자가 보험의 목적을 양도한 때에는 양수인은 보험계약상의 의무를 승계한 것으로 간주한다.","o":"양수인은 권리와 의무를 승계한 것으로 「추정」한다(간주 아님).","src":"상법 제679조① | 기출 2025-19"}]},"화재보험계약과 화재보험증권":{"묶음":[{"머리":"화재보험자의 책임","줄":[{"t":"화재보험계약의 보험자는 화재로 인하여 생길 손해를 보상할 책임이 있다.","src":"상법 제683조 | 기출 2026-23"},{"t":"화재와 손해 사이에 상당인과관계가 필요하다.","src":"기출 2021-23 | 기출 2023-24"},{"t":"보험자는 화재의 소방 또는 손해의 감소에 필요한 조치로 인하여 생긴 손해를 보상할 책임이 있다(진화용 물로 보험목적이 훼손된 손해 포함).","src":"상법 제684조 | 기출 2022-15 | 기출 2023-24 | 기출 2024-23 | 기출 2026-23"},{"t":"화재 건물의 철거비와 폐기물처리비는 화재와 상당인과관계가 있는 건물수리비에 포함된다.","src":"기출 2021-23 | 기출 2024-23 | 기출 2026-23"},{"t":"화재로 다른 곳에 옮겨놓은 물건의 도난으로 인한 손해는 보상 대상이 아니다.","src":"기출 2024-23"},{"t":"연소 작용이 아닌 열의 작용으로 발생한 손해는 보상하지 않는다.","src":"기출 2023-24"},{"t":"가연성 목조교량도 화재보험의 목적이 될 수 있다.","src":"기출 2021-23"}]},{"머리":"화재보험증권(제685조)","줄":[{"t":"제666조 기재사항 외에 건물이 목적이면 그 소재지, 구조와 용도를 기재한다.","src":"상법 제685조1호 | 기출 2021-24 | 기출 2024-24 | 기출 2025-25"},{"t":"동산이 목적이면 그 존치한 장소의 상태와 용도를 기재한다(위치한 장소만이 아님).","src":"상법 제685조2호 | 기출 2024-24 | 기출 2025-24 | 기출 2026-24"},{"t":"보험가액을 정한 때에는 그 가액을 기재한다.","src":"상법 제685조3호 | 기출 2021-24 | 기출 2025-25"},{"t":"제666조의 기재사항: 보험의 목적, 사고의 성질, 보험금액, 보험료와 지급방법, 보험기간의 시기·종기, 무효와 실권 사유, 보험계약자의 주소·성명, 피보험자의 주소·성명, 계약 연월일, 증권 작성지·작성년월일.","src":"상법 제666조"},{"t":"기재사항이 아닌 것: 설계감리법인·시공자의 주소와 성명, 보험계약자의 주민등록번호, 보험금액의 지급방법·시기.","src":"기출 2021-24 | 기출 2025-25 | 기출 2026-24"}]},{"머리":"피보험이익과 일부보험","줄":[{"t":"소유자와 저당권자는 각각 다른 피보험이익을 가지며 각자 독립한 화재보험계약을 체결할 수 있다.","src":"기출 2023-24 | 기출 2024-24"},{"t":"건물의 보험가액 일부를 보험에 붙인 경우, 다른 약정이 없으면 보험금액의 보험가액에 대한 비율로 보상한다.","src":"상법 제674조 | 기출 2024-24"},{"t":"보험료 잔액이 있으면 지급기일 미도래라도 보상금에서 공제할 수 있다.","src":"상법 제677조 | 기출 2023-21"},{"t":"건물 양도 시 양수인은 권리·의무를 승계한 것으로 추정하고, 양도인 또는 양수인은 보험자에게 지체없이 통지한다.","src":"상법 제679조 | 기출 2023-21"},{"t":"보험자는 다른 보험자와 재보험계약을 체결할 수 있다.","src":"상법 제661조 | 기출 2023-21"}]}],"함정":[{"x":"화재가 발생한 건물을 수리하면서 지출한 철거비와 폐기물처리비는 화재와 상당인과 관계가 있는 건물수리비에는 포함되지 않는다.","o":"화재 건물의 철거비와 폐기물처리비는 화재와 상당인과관계 있는 건물수리비에 포함된다.","src":"기출 2024-23 | 기출 2021-23"},{"x":"피보험자가 화재 진화를 위해 살포한 물로 보험목적이 훼손된 손해는 보상하지 않는다.","o":"화재의 소방 또는 손해 감소에 필요한 조치로 생긴 손해(진화용 물로 인한 훼손)는 보험자가 보상한다.","src":"상법 제684조 | 기출 2021-23"},{"x":"불에 탈 수 있는 목조교량은 화재보험의 목적이 될 수 없다.","o":"가연성 목조교량도 화재보험의 목적이 될 수 있다.","src":"기출 2021-23 | 기출 2021-23"},{"x":"보험의 목적에 관하여 보험자가 부담할 손해가 생긴 경우에는 그 후 그 목적이 보험 자가 부담하지 아니하는 보험사고의 발생으로 인하여 멸실된 때에는 보험자는 이미 생긴 손해를 보상할 책임을 면한다.","o":"보험자가 부담할 손해가 생긴 후 그 목적이 보험자 부담 외 사고로 멸실되어도 이미 생긴 손해를 보상할 책임을 면하지 못한다.","src":"상법 제675조 | 기출 2022-20"},{"x":"A보험회사가 甲으로부터 보험료의 지급을 받지 아니한 잔액이 있더라도 그 지급기일이 아직 도래하지 아니한 때에는, A보험회사는 甲에게 손해를 보상할 경우에 보상할 금액 에서 그 잔액을 공제하여서는 아니된다.","o":"보험료 잔액이 있으면 지급기일이 도래하지 아니한 때라도 보상할 금액에서 공제할 수 있다.","src":"상법 제677조 | 기출 2023-21"},{"x":"동일한 건물에 관한 화재보험계약일 경우 그 소유자와 담보권자가 갖는 피보험이익은 같다.","o":"동일 건물이라도 소유자와 담보권자의 피보험이익은 다르다.","src":"기출 2024-24 | 기출 2023-24"},{"x":"건물을 보험의 목적으로 한 때 그 보험가액의 일부를 보험에 붙인 경우, 당사자간에 다른 약정이 없다면 보험자는 보험금액의 한도내에서 그 손해를 보상할 책임을 진다.","o":"일부보험은 다른 약정이 없으면 보험금액의 보험가액에 대한 비율로 보상하고, 약정이 있으면 보험금액 한도에서 전부 보상한다.","src":"상법 제674조 | 기출 2024-24"},{"x":"화재가 발생한 건물을 수리하면서 지출한 철거비와 폐기물처리비는 화재와 상당인과 관계가 있는 건물수리비에는 포함되지 않는다.","o":"화재 건물의 철거비와 폐기물처리비는 화재와 상당인과관계 있는 건물수리비에 포함된다.","src":"기출 2024-23 | 기출 2026-23"}]},"집합보험":{"묶음":[{"머리":"집합보험의 의의","줄":[{"t":"집합보험: 경제적으로 독립한 여러 물건의 집합물을 하나의 보험의 목적으로 한 보험. 집합된 물건을 일괄하여 보험의 목적으로 한다.","src":"상법 제686조 | 기출 2021-25 | 기출 2024-25 | 기출 2025-23 | 기출 2026-25"}]},{"머리":"가족·사용인의 물건(제686조)","줄":[{"t":"집합된 물건을 일괄하여 보험의 목적으로 한 때에는 피보험자의 가족과 사용인의 물건도 보험의 목적에 포함된 것으로 한다.","src":"상법 제686조 | 기출 2021-25 | 기출 2023-25 | 기출 2024-25 | 기출 2025-23 | 기출 2026-25"},{"t":"이 경우 그 보험은 그 가족 또는 사용인을 위하여서도 체결한 것으로 본다.","src":"상법 제686조 후단 | 기출 2023-25 | 기출 2024-25 | 기출 2026-25"}]},{"머리":"물건의 교체(제687조)","줄":[{"t":"보험의 목적에 속한 물건이 보험기간 중 수시로 교체된 경우에도 「보험사고의 발생 시」에 현존한 물건은 보험의 목적에 포함된 것으로 한다.","src":"상법 제687조 | 기출 2021-25 | 기출 2023-25 | 기출 2025-23"},{"t":"보험계약 체결 시에 현존하였지만 사고 발생 시에 현존하지 않는 물건은 포함되지 않는다.","src":"상법 제687조 | 기출 2024-25 | 기출 2026-25"}]}],"함정":[{"x":"집합된 물건을 일괄하여 보험의 목적으로 한 때에는 피보험자에게 고용된 사용자의 물건은 보험목적에 포함되지 않는다.","o":"집합보험에서 피보험자의 가족과 사용인의 물건도 보험의 목적에 포함된 것으로 한다.","src":"상법 제686조 | 기출 2025-23"}]}};
